#include <stdio.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_heap_caps.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima_deploy";

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Model Deploy on ESP32-S3-EYE ===");

    // 打印可用内存
    ESP_LOGI(TAG, "Free heap: %lu bytes", esp_get_free_heap_size());
    ESP_LOGI(TAG, "Free PSRAM: %d bytes", heap_caps_get_free_size(MALLOC_CAP_SPIRAM));

    // -------------------------------------------------------
    // 1. 从 flash 分区加载模型
    //    第一个参数 "model" 对应 partitions.csv 中的分区名
    // -------------------------------------------------------
    ESP_LOGI(TAG, "Loading model from flash partition...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    ESP_LOGI(TAG, "Model loaded successfully!");

    // -------------------------------------------------------
    // 2. 打印模型 memory 和 latency 信息（调试用）
    // -------------------------------------------------------
    model->profile();

    // -------------------------------------------------------
    // 3. 测试模型推理正确性（如果导出时包含了 test data）
    // -------------------------------------------------------
    esp_err_t test_ret = model->test();
    if (test_ret == ESP_OK) {
        ESP_LOGI(TAG, "Model test PASSED!");
    } else {
        ESP_LOGW(TAG, "Model test FAILED or no test data embedded.");
    }

    // -------------------------------------------------------
    // 4. 手动推理示例
    //    输入: (1, 224, 224, 3) int16, exponent = -14
    //    输出: (1, 1) int16, exponent = -12
    //
    //    实际使用时，你需要从相机获取图片并预处理为 224x224
    //    这里用全零数据做演示
    // -------------------------------------------------------
    ESP_LOGI(TAG, "Running dummy inference...");

    // 获取模型输入 tensor 信息
    auto &inputs = model->get_inputs();
    if (!inputs.empty()) {
        auto input_tensor = inputs.begin()->second;
        int input_size = input_tensor->get_size();
        ESP_LOGI(TAG, "Input tensor size: %d elements", input_size);

        // 用零填充输入（实际应用中替换为图像数据）
        int16_t *input_data = (int16_t *)input_tensor->get_element_ptr();
        memset(input_data, 0, input_size * sizeof(int16_t));

        // 运行推理
        model->run();

        // 读取输出
        auto &outputs = model->get_outputs();
        if (!outputs.empty()) {
            auto output_tensor = outputs.begin()->second;
            int16_t *raw_output = (int16_t *)output_tensor->get_element_ptr();
            int exponent = output_tensor->get_exponent();
            float score = raw_output[0] * powf(2.0f, (float)exponent);

            ESP_LOGI(TAG, "Raw output: %d, exponent: %d", raw_output[0], exponent);
            ESP_LOGI(TAG, "Aesthetic score: %.4f (range: 1-10, higher is better)", score);
        }
    }

    ESP_LOGI(TAG, "=== Done! ===");
    ESP_LOGI(TAG, "Free heap after inference: %lu bytes", esp_get_free_heap_size());

    // 清理
    delete model;

    // 保持运行
    while (1) {
        vTaskDelay(pdMS_TO_TICKS(10000));
    }
}

