#include <stdio.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_heap_caps.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima_deploy";

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Model Deploy on ESP32-S3-EYE ===");

    // 打印可用内存
    ESP_LOGI(TAG, "Free heap: %lu bytes", esp_get_free_heap_size());
    ESP_LOGI(TAG, "Free PSRAM: %d bytes", heap_caps_get_free_size(MALLOC_CAP_SPIRAM));

    // -------------------------------------------------------
    // 1. 从 flash 分区加载模型
    //    第一个参数 "model" 对应 partitions.csv 中的分区名
    // -------------------------------------------------------
    ESP_LOGI(TAG, "Loading model from flash partition...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);

    // 检查模型是否加载成功（通过检查输入是否为空判断）
    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "=== MODEL LOAD FAILED ===");
        ESP_LOGE(TAG, "This model uses W8A16 quant type which is not supported on ESP32-S3.");
        ESP_LOGE(TAG, "You need to re-export the model with target='esp32s3' using ESP-PPQ.");
        ESP_LOGE(TAG, "Supported quant types: SYMM_8BIT (W8A8) or SYMM_16BIT (S16).");
        ESP_LOGE(TAG, "Device will stay idle. Please flash a compatible model.");

        // 停在这里，不再做任何事情
        while (1) {
            vTaskDelay(pdMS_TO_TICKS(60000));
        }
    }

    ESP_LOGI(TAG, "Model loaded successfully!");

    // -------------------------------------------------------
    // 2. 打印模型 memory 和 latency 信息（调试用）
    // -------------------------------------------------------
    model->profile();

    // -------------------------------------------------------
    // 3. 测试模型推理正确性（如果导出时包含了 test data）
    // -------------------------------------------------------
    esp_err_t test_ret = model->test();
    if (test_ret == ESP_OK) {
        ESP_LOGI(TAG, "Model test PASSED!");
    } else {
        ESP_LOGW(TAG, "Model test FAILED or no test data embedded.");
    }

    // -------------------------------------------------------
    // 4. 手动推理示例
    //    输入: (1, 224, 224, 3) int16, exponent = -14
    //    输出: (1, 1) int16, exponent = -12
    //
    //    实际使用时，你需要从相机获取图片并预处理为 224x224
    //    这里用全零数据做演示
    // -------------------------------------------------------
    ESP_LOGI(TAG, "Running dummy inference...");

    auto input_tensor = inputs.begin()->second;
    int input_size = input_tensor->get_size();
    ESP_LOGI(TAG, "Input tensor size: %d elements", input_size);

    // 用零填充输入（实际应用中替换为图像数据）
    int16_t *input_data = (int16_t *)input_tensor->get_element_ptr();
    memset(input_data, 0, input_size * sizeof(int16_t));

    // 运行推理
    model->run();

    // 读取输出
    auto &outputs = model->get_outputs();
    if (!outputs.empty()) {
        auto output_tensor = outputs.begin()->second;
        int16_t *raw_output = (int16_t *)output_tensor->get_element_ptr();
        int exponent = output_tensor->get_exponent();
        float score = raw_output[0] * powf(2.0f, (float)exponent);

        ESP_LOGI(TAG, "Raw output: %d, exponent: %d", raw_output[0], exponent);
        ESP_LOGI(TAG, "Aesthetic score: %.4f (range: 1-10, higher is better)", score);
    }

    ESP_LOGI(TAG, "=== Done! ===");
    ESP_LOGI(TAG, "Free heap after inference: %lu bytes", esp_get_free_heap_size());

    // 清理
    delete model;

    // 保持运行
    while (1) {
        vTaskDelay(pdMS_TO_TICKS(10000));
    }
}

/**
 * NIMA Aesthetic Score - ESP32-S3-EYE
 *
 * 实时从摄像头取图 → 缩放到 224x224 → 模型推理 → LCD 显示分数
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_heap_caps.h"
#include "esp_camera.h"
#include "esp_lcd_panel_ops.h"
#include "bsp/esp-bsp.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima";

// NIMA 模型输入尺寸
#define MODEL_W 224
#define MODEL_H 224
#define MODEL_C 3

/**
 * 将 RGB565 帧缩放到 224x224 并转为 int16 归一化 [-1, 1]
 * 输入 exponent = -14，所以 int16 值 = float_val * 2^14
 *   float 1.0  → int16 16384
 *   float -1.0 → int16 -16384
 */
static void preprocess_rgb565_to_int16(const uint8_t *rgb565_buf, int src_w, int src_h,
                                        int16_t *dst, int dst_w, int dst_h)
{
    const float scale_x = (float)src_w / dst_w;
    const float scale_y = (float)src_h / dst_h;
    const float quant_scale = 16384.0f; // 2^14

    for (int y = 0; y < dst_h; y++) {
        int src_y = (int)(y * scale_y);
        if (src_y >= src_h) src_y = src_h - 1;

        for (int x = 0; x < dst_w; x++) {
            int src_x = (int)(x * scale_x);
            if (src_x >= src_w) src_x = src_w - 1;

            // RGB565: RRRRRGGG GGGBBBBB (big-endian in camera buffer)
            int idx = (src_y * src_w + src_x) * 2;
            uint16_t pixel = (rgb565_buf[idx] << 8) | rgb565_buf[idx + 1];
            uint8_t r = (pixel >> 11) & 0x1F;
            uint8_t g = (pixel >> 5) & 0x3F;
            uint8_t b = pixel & 0x1F;

            // 扩展到 0-255
            float rf = (r * 255.0f / 31.0f);
            float gf = (g * 255.0f / 63.0f);
            float bf = (b * 255.0f / 31.0f);

            // 归一化到 [-1, 1]: val / 127.5 - 1.0
            float r_norm = rf / 127.5f - 1.0f;
            float g_norm = gf / 127.5f - 1.0f;
            float b_norm = bf / 127.5f - 1.0f;

            // 量化为 int16 (exponent = -14)
            int dst_idx = (y * dst_w + x) * 3;
            dst[dst_idx + 0] = (int16_t)(r_norm * quant_scale);
            dst[dst_idx + 1] = (int16_t)(g_norm * quant_scale);
            dst[dst_idx + 2] = (int16_t)(b_norm * quant_scale);
        }
    }
}

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Aesthetic Score - ESP32-S3-EYE ===");
    ESP_LOGI(TAG, "Free PSRAM: %d KB", heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024);

    // ========== 1. 初始化 BSP I2C（摄像头需要） ==========
    bsp_i2c_init();

    // ========== 2. 初始化摄像头 ==========
    ESP_LOGI(TAG, "Initializing camera...");
    const camera_config_t cam_cfg = BSP_CAMERA_DEFAULT_CONFIG;
    esp_err_t err = esp_camera_init(&cam_cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Camera init failed: %s", esp_err_to_name(err));
        return;
    }
    sensor_t *s = esp_camera_sensor_get();
    s->set_vflip(s, BSP_CAMERA_VFLIP);
    s->set_hmirror(s, BSP_CAMERA_HMIRROR);
    ESP_LOGI(TAG, "Camera OK");

    // ========== 3. 初始化 LCD 显示 ==========
    ESP_LOGI(TAG, "Initializing display...");
    lv_display_t *disp = bsp_display_start();
    if (!disp) {
        ESP_LOGE(TAG, "Display init failed");
        return;
    }
    bsp_display_backlight_on();

    // 创建 LVGL UI 元素
    bsp_display_lock(0);
    lv_obj_t *scr = lv_display_get_screen_active(disp);

    // 画布用于显示相机图像（240x240 LCD）
    static lv_color_t canvas_buf[240 * 240] __attribute__((aligned(4)));
    lv_obj_t *canvas = lv_canvas_create(scr);
    lv_canvas_set_buffer(canvas, canvas_buf, 240, 240, LV_COLOR_FORMAT_RGB565);
    lv_obj_center(canvas);

    // 分数标签
    lv_obj_t *label = lv_label_create(scr);
    lv_obj_set_style_text_font(label, &lv_font_montserrat_28, 0);
    lv_obj_set_style_text_color(label, lv_color_hex(0x00FF00), 0);
    lv_obj_set_style_bg_color(label, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(label, LV_OPA_70, 0);
    lv_obj_set_style_pad_all(label, 5, 0);
    lv_label_set_text(label, "Score: --");
    lv_obj_align(label, LV_ALIGN_TOP_MID, 0, 5);

    bsp_display_unlock();
    ESP_LOGI(TAG, "Display OK");

    // ========== 4. 加载 NIMA 模型 ==========
    ESP_LOGI(TAG, "Loading NIMA model...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);

    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model load FAILED - quant type not supported on this chip");
        bsp_display_lock(0);
        lv_label_set_text(label, "Model Error!");
        bsp_display_unlock();
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    ESP_LOGI(TAG, "Model loaded OK!");

    // 获取输入 tensor 指针
    auto input_tensor = inputs.begin()->second;
    int16_t *model_input = (int16_t *)input_tensor->get_element_ptr();

    // ========== 5. 主循环：取图 → 推理 → 显示 ==========
    ESP_LOGI(TAG, "Starting inference loop...");
    int frame_count = 0;
    float last_score = 0;

    while (1) {
        // 从摄像头获取一帧
        camera_fb_t *fb = esp_camera_fb_get();
        if (!fb) {
            ESP_LOGW(TAG, "Camera capture failed");
            vTaskDelay(pdMS_TO_TICKS(100));
            continue;
        }

        // 显示相机画面到 LCD（直接拷贝 RGB565 到 canvas）
        bsp_display_lock(0);
        // 相机输出是 QVGA(320x240) RGB565，LCD 是 240x240
        // 简单裁剪中间 240x240 区域
        int cam_w = fb->width;
        int cam_h = fb->height;
        int offset_x = (cam_w - 240) / 2;
        if (offset_x < 0) offset_x = 0;
        for (int row = 0; row < 240 && row < cam_h; row++) {
            memcpy(&canvas_buf[row * 240],
                   &fb->buf[(row * cam_w + offset_x) * 2],
                   240 * 2);
        }
        lv_obj_invalidate(canvas);
        bsp_display_unlock();

        // 每 5 帧推理一次（节省算力，推理约 500ms-1s）
        frame_count++;
        if (frame_count % 5 == 1) {
            // 预处理：RGB565 → 224x224 int16
            preprocess_rgb565_to_int16(fb->buf, cam_w, cam_h,
                                       model_input, MODEL_W, MODEL_H);

            // 释放相机 buffer（推理前释放以节省内存）
            esp_camera_fb_return(fb);
            fb = NULL;

            // 运行推理
            model->run();

            // 读取输出
            auto &outputs = model->get_outputs();
            if (!outputs.empty()) {
                auto output_tensor = outputs.begin()->second;
                int16_t *raw = (int16_t *)output_tensor->get_element_ptr();
                int exponent = output_tensor->get_exponent();
                last_score = raw[0] * powf(2.0f, (float)exponent);

                // 限制在合理范围 [1, 10]
                if (last_score < 1.0f) last_score = 1.0f;
                if (last_score > 10.0f) last_score = 10.0f;

                ESP_LOGI(TAG, "Score: %.2f (raw=%d, exp=%d)", last_score, raw[0], exponent);
            }

            // 更新 LCD 上的分数
            bsp_display_lock(0);
            char score_str[32];
            snprintf(score_str, sizeof(score_str), "Score: %.1f / 10", last_score);
            lv_label_set_text(label, score_str);

            // 根据分数变色
            if (last_score >= 6.0f) {
                lv_obj_set_style_text_color(label, lv_color_hex(0x00FF00), 0); // 绿
            } else if (last_score >= 4.5f) {
                lv_obj_set_style_text_color(label, lv_color_hex(0xFFFF00), 0); // 黄
            } else {
                lv_obj_set_style_text_color(label, lv_color_hex(0xFF0000), 0); // 红
            }
            bsp_display_unlock();
        } else {
            // 非推理帧，直接释放
            if (fb) {
                esp_camera_fb_return(fb);
            }
        }

        // 让出 CPU 给 LVGL 刷新
        vTaskDelay(pdMS_TO_TICKS(30));
    }
}

/**
 * NIMA Aesthetic Score - ESP32-S3-EYE
 *
 * 实时从摄像头取图 → 缩放到 224x224 → 模型推理 → 串口输出分数
 *
 * 注意：本版本只做相机+推理+串口输出，不涉及 LCD 显示。
 *       确认推理流程正确后再加 LCD。
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_heap_caps.h"
#include "esp_camera.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima";

// NIMA 模型输入尺寸
#define MODEL_W 224
#define MODEL_H 224
#define MODEL_C 3

// ESP32-S3-EYE 相机引脚定义
#define CAM_PIN_PWDN    -1
#define CAM_PIN_RESET   -1
#define CAM_PIN_XCLK    15
#define CAM_PIN_SIOD    4
#define CAM_PIN_SIOC    5
#define CAM_PIN_D7      16
#define CAM_PIN_D6      17
#define CAM_PIN_D5      18
#define CAM_PIN_D4      12
#define CAM_PIN_D3      10
#define CAM_PIN_D2      8
#define CAM_PIN_D1      9
#define CAM_PIN_D0      11
#define CAM_PIN_VSYNC   6
#define CAM_PIN_HREF    7
#define CAM_PIN_PCLK    13

/**
 * 将 RGB565 帧缩放到 224x224 并转为 int16 归一化 [-1, 1]
 * 输入 exponent = -14，所以 int16 值 = float_val * 2^14
 */
static void preprocess_rgb565_to_int16(const uint8_t *rgb565_buf, int src_w, int src_h,
                                        int16_t *dst, int dst_w, int dst_h)
{
    const float scale_x = (float)src_w / dst_w;
    const float scale_y = (float)src_h / dst_h;
    const float quant_scale = 16384.0f; // 2^14

    for (int y = 0; y < dst_h; y++) {
        int src_y = (int)(y * scale_y);
        if (src_y >= src_h) src_y = src_h - 1;

        for (int x = 0; x < dst_w; x++) {
            int src_x = (int)(x * scale_x);
            if (src_x >= src_w) src_x = src_w - 1;

            // RGB565 little-endian (esp32-camera default)
            int idx = (src_y * src_w + src_x) * 2;
            uint16_t pixel = rgb565_buf[idx] | (rgb565_buf[idx + 1] << 8);
            uint8_t r = (pixel >> 11) & 0x1F;
            uint8_t g = (pixel >> 5) & 0x3F;
            uint8_t b = pixel & 0x1F;

            // 扩展到 0-255
            float rf = r * (255.0f / 31.0f);
            float gf = g * (255.0f / 63.0f);
            float bf = b * (255.0f / 31.0f);

            // 归一化到 [-1, 1]
            float r_norm = rf / 127.5f - 1.0f;
            float g_norm = gf / 127.5f - 1.0f;
            float b_norm = bf / 127.5f - 1.0f;

            // NHWC 格式 (y, x, channel)
            int dst_idx = (y * dst_w + x) * 3;
            dst[dst_idx + 0] = (int16_t)(r_norm * quant_scale);
            dst[dst_idx + 1] = (int16_t)(g_norm * quant_scale);
            dst[dst_idx + 2] = (int16_t)(b_norm * quant_scale);
        }
    }
}

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Aesthetic Score - ESP32-S3-EYE ===");
    ESP_LOGI(TAG, "Free heap: %lu bytes", esp_get_free_heap_size());
    ESP_LOGI(TAG, "Free PSRAM: %d bytes", heap_caps_get_free_size(MALLOC_CAP_SPIRAM));

    // ========== 1. 初始化摄像头 ==========
    ESP_LOGI(TAG, "Initializing camera...");
    camera_config_t cam_config = {};
    cam_config.pin_pwdn = CAM_PIN_PWDN;
    cam_config.pin_reset = CAM_PIN_RESET;
    cam_config.pin_xclk = CAM_PIN_XCLK;
    cam_config.pin_sccb_sda = CAM_PIN_SIOD;
    cam_config.pin_sccb_scl = CAM_PIN_SIOC;
    cam_config.pin_d7 = CAM_PIN_D7;
    cam_config.pin_d6 = CAM_PIN_D6;
    cam_config.pin_d5 = CAM_PIN_D5;
    cam_config.pin_d4 = CAM_PIN_D4;
    cam_config.pin_d3 = CAM_PIN_D3;
    cam_config.pin_d2 = CAM_PIN_D2;
    cam_config.pin_d1 = CAM_PIN_D1;
    cam_config.pin_d0 = CAM_PIN_D0;
    cam_config.pin_vsync = CAM_PIN_VSYNC;
    cam_config.pin_href = CAM_PIN_HREF;
    cam_config.pin_pclk = CAM_PIN_PCLK;
    cam_config.xclk_freq_hz = 16000000;
    cam_config.ledc_timer = LEDC_TIMER_0;
    cam_config.ledc_channel = LEDC_CHANNEL_0;
    cam_config.pixel_format = PIXFORMAT_RGB565;
    cam_config.frame_size = FRAMESIZE_QVGA;  // 320x240
    cam_config.jpeg_quality = 12;
    cam_config.fb_count = 2;
    cam_config.fb_location = CAMERA_FB_IN_PSRAM;
    cam_config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;

    esp_err_t err = esp_camera_init(&cam_config);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Camera init failed: 0x%x", err);
        return;
    }

    // 设置翻转（ESP32-S3-EYE 摄像头需要 vflip）
    sensor_t *s = esp_camera_sensor_get();
    if (s) {
        s->set_vflip(s, 1);
        s->set_hmirror(s, 0);
    }
    ESP_LOGI(TAG, "Camera OK (320x240 RGB565)");

    // ========== 2. 加载 NIMA 模型 ==========
    ESP_LOGI(TAG, "Loading NIMA model from flash partition...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);

    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "MODEL LOAD FAILED!");
        ESP_LOGE(TAG, "Quant type not supported. Halting.");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    ESP_LOGI(TAG, "Model loaded OK!");

    // 获取输入 tensor
    auto input_tensor = inputs.begin()->second;
    int16_t *model_input = (int16_t *)input_tensor->get_element_ptr();
    int input_size = input_tensor->get_size();
    ESP_LOGI(TAG, "Model input size: %d elements", input_size);

    // ========== 3. 主循环：取图 → 推理 → 打印分数 ==========
    ESP_LOGI(TAG, "Starting inference loop (every 2 seconds)...");

    while (1) {
        // 从摄像头获取一帧
        camera_fb_t *fb = esp_camera_fb_get();
        if (!fb) {
            ESP_LOGW(TAG, "Camera capture failed, retrying...");
            vTaskDelay(pdMS_TO_TICKS(500));
            continue;
        }

        ESP_LOGI(TAG, "Got frame: %dx%d, %d bytes", fb->width, fb->height, fb->len);

        // 预处理：RGB565 320x240 → int16 224x224
        preprocess_rgb565_to_int16(fb->buf, fb->width, fb->height,
                                    model_input, MODEL_W, MODEL_H);

        // 释放相机 buffer
        esp_camera_fb_return(fb);

        // 运行推理
        ESP_LOGI(TAG, "Running inference...");
        int64_t start = esp_timer_get_time();
        model->run();
        int64_t elapsed = esp_timer_get_time() - start;
        ESP_LOGI(TAG, "Inference time: %lld ms", elapsed / 1000);

        // 读取输出
        auto &outputs = model->get_outputs();
        if (!outputs.empty()) {
            auto output_tensor = outputs.begin()->second;
            int16_t *raw = (int16_t *)output_tensor->get_element_ptr();
            int exponent = output_tensor->get_exponent();
            float score = raw[0] * powf(2.0f, (float)exponent);

            // 限制在合理范围
            if (score < 1.0f) score = 1.0f;
            if (score > 10.0f) score = 10.0f;

            ESP_LOGI(TAG, ">>> AESTHETIC SCORE: %.2f / 10 <<<  (raw=%d, exp=%d)",
                     score, raw[0], exponent);
        }

        ESP_LOGI(TAG, "Free heap: %lu, PSRAM free: %d",
                 esp_get_free_heap_size(),
                 heap_caps_get_free_size(MALLOC_CAP_SPIRAM));

        // 每 2 秒推理一次
        vTaskDelay(pdMS_TO_TICKS(2000));
    }
}

/**
 * NIMA Aesthetic Score - ESP32-S3-EYE
 *
 * 相机实时取图 → LCD 显示画面 → 定时推理 → 叠加分数显示
 * 使用 esp_lcd 直接驱动 ST7789（不依赖 LVGL）
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
