#include "esp_heap_caps.h"
#include "esp_camera.h"
#include "esp_lcd_panel_io.h"
#include "esp_lcd_panel_vendor.h"
#include "esp_lcd_panel_ops.h"
#include "driver/spi_master.h"
#include "driver/gpio.h"
#include "driver/ledc.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima";

// ==================== 硬件引脚定义 ====================

// ESP32-S3-EYE 相机引脚
#define CAM_PIN_PWDN    -1
#define CAM_PIN_RESET   -1
#define CAM_PIN_XCLK    15
#define CAM_PIN_SIOD    4
#define CAM_PIN_SIOC    5
#define CAM_PIN_D7      16
#define CAM_PIN_D6      17
#define CAM_PIN_D5      18
#define CAM_PIN_D4      12
#define CAM_PIN_D3      10
#define CAM_PIN_D2      8
#define CAM_PIN_D1      9
#define CAM_PIN_D0      11
#define CAM_PIN_VSYNC   6
#define CAM_PIN_HREF    7
#define CAM_PIN_PCLK    13

// ESP32-S3-EYE LCD 引脚 (ST7789, 240x240, SPI)
#define LCD_PIN_MOSI    47
#define LCD_PIN_CLK     21
#define LCD_PIN_CS      44
#define LCD_PIN_DC      43
#define LCD_PIN_RST     -1
#define LCD_PIN_BL      48
#define LCD_H_RES       240
#define LCD_V_RES       240
#define LCD_SPI_HOST    SPI3_HOST

// 模型参数
#define MODEL_W 224
#define MODEL_H 224

// ==================== LCD 初始化 ====================

static esp_lcd_panel_handle_t lcd_panel = NULL;

static void lcd_backlight_init(void)
{
    ledc_timer_config_t timer_cfg = {};
    timer_cfg.speed_mode = LEDC_LOW_SPEED_MODE;
    timer_cfg.duty_resolution = LEDC_TIMER_8_BIT;
    timer_cfg.timer_num = LEDC_TIMER_1;
    timer_cfg.freq_hz = 5000;
    timer_cfg.clk_cfg = LEDC_AUTO_CLK;
    ledc_timer_config(&timer_cfg);

    ledc_channel_config_t ch_cfg = {};
    ch_cfg.gpio_num = LCD_PIN_BL;
    ch_cfg.speed_mode = LEDC_LOW_SPEED_MODE;
    ch_cfg.channel = LEDC_CHANNEL_1;
    ch_cfg.timer_sel = LEDC_TIMER_1;
    ch_cfg.duty = 255; // 全亮
    ch_cfg.hpoint = 0;
    ledc_channel_config(&ch_cfg);
}

static esp_err_t lcd_init(void)
{
    lcd_backlight_init();

    spi_bus_config_t bus_cfg = {};
    bus_cfg.mosi_io_num = LCD_PIN_MOSI;
    bus_cfg.miso_io_num = -1;
    bus_cfg.sclk_io_num = LCD_PIN_CLK;
    bus_cfg.quadwp_io_num = -1;
    bus_cfg.quadhd_io_num = -1;
    bus_cfg.max_transfer_sz = LCD_H_RES * LCD_V_RES * 2;
    ESP_ERROR_CHECK(spi_bus_initialize(LCD_SPI_HOST, &bus_cfg, SPI_DMA_CH_AUTO));

    esp_lcd_panel_io_handle_t io_handle = NULL;
    esp_lcd_panel_io_spi_config_t io_cfg = {};
    io_cfg.dc_gpio_num = LCD_PIN_DC;
    io_cfg.cs_gpio_num = LCD_PIN_CS;
    io_cfg.pclk_hz = 80 * 1000 * 1000;
    io_cfg.lcd_cmd_bits = 8;
    io_cfg.lcd_param_bits = 8;
    io_cfg.spi_mode = 0;
    io_cfg.trans_queue_depth = 10;
    ESP_ERROR_CHECK(esp_lcd_new_panel_io_spi(LCD_SPI_HOST, &io_cfg, &io_handle));

    esp_lcd_panel_dev_config_t panel_cfg = {};
    panel_cfg.reset_gpio_num = LCD_PIN_RST;
    panel_cfg.rgb_ele_order = LCD_RGB_ELEMENT_ORDER_RGB;
    panel_cfg.bits_per_pixel = 16;
    ESP_ERROR_CHECK(esp_lcd_new_panel_st7789(io_handle, &panel_cfg, &lcd_panel));

    ESP_ERROR_CHECK(esp_lcd_panel_reset(lcd_panel));
    ESP_ERROR_CHECK(esp_lcd_panel_init(lcd_panel));
    ESP_ERROR_CHECK(esp_lcd_panel_invert_color(lcd_panel, true));
    ESP_ERROR_CHECK(esp_lcd_panel_swap_xy(lcd_panel, false));
    ESP_ERROR_CHECK(esp_lcd_panel_mirror(lcd_panel, true, true));
    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(lcd_panel, true));

    return ESP_OK;
}

// ==================== 分数叠加绘制 ====================

// 简易 5x7 数字字模（0-9 和 '.' '/' ' '）
static const uint8_t font_5x7[][7] = {
    // 0
    {0x0E,0x11,0x13,0x15,0x19,0x11,0x0E},
    // 1
    {0x04,0x0C,0x04,0x04,0x04,0x04,0x0E},
    // 2
    {0x0E,0x11,0x01,0x06,0x08,0x10,0x1F},
    // 3
    {0x0E,0x11,0x01,0x06,0x01,0x11,0x0E},
    // 4
    {0x02,0x06,0x0A,0x12,0x1F,0x02,0x02},
    // 5
    {0x1F,0x10,0x1E,0x01,0x01,0x11,0x0E},
    // 6
    {0x06,0x08,0x10,0x1E,0x11,0x11,0x0E},
    // 7
    {0x1F,0x01,0x02,0x04,0x08,0x08,0x08},
    // 8
    {0x0E,0x11,0x11,0x0E,0x11,0x11,0x0E},
    // 9
    {0x0E,0x11,0x11,0x0F,0x01,0x02,0x0C},
    // '.' = index 10
    {0x00,0x00,0x00,0x00,0x00,0x00,0x04},
    // '/' = index 11
    {0x01,0x02,0x02,0x04,0x08,0x08,0x10},
    // ' ' = index 12
    {0x00,0x00,0x00,0x00,0x00,0x00,0x00},
};

static int char_to_font_idx(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c == '.') return 10;
    if (c == '/') return 11;
    return 12; // space
}

/**
 * 在 RGB565 buffer 上绘制文字
 * scale=2 表示每个像素放大 2 倍
 */
static void draw_string_on_rgb565(uint16_t *buf, int buf_w, int buf_h,
                                   int start_x, int start_y,
                                   const char *str, uint16_t color, int scale)
{
    int cursor_x = start_x;
    for (int i = 0; str[i] != '\0'; i++) {
        int fi = char_to_font_idx(str[i]);
        for (int row = 0; row < 7; row++) {
            uint8_t bits = font_5x7[fi][row];
            for (int col = 0; col < 5; col++) {
                if (bits & (0x10 >> col)) {
                    // 放大绘制
                    for (int sy = 0; sy < scale; sy++) {
                        for (int sx = 0; sx < scale; sx++) {
                            int px = cursor_x + col * scale + sx;
                            int py = start_y + row * scale + sy;
                            if (px >= 0 && px < buf_w && py >= 0 && py < buf_h) {
                                buf[py * buf_w + px] = color;
                            }
                        }
                    }
                }
            }
        }
        cursor_x += 6 * scale; // 5 pixels + 1 gap
    }
}

// ==================== 预处理 ====================

static void preprocess_rgb565_to_int16(const uint8_t *rgb565_buf, int src_w, int src_h,
                                        int16_t *dst, int dst_w, int dst_h)
{
    const float scale_x = (float)src_w / dst_w;
    const float scale_y = (float)src_h / dst_h;
    const float quant_scale = 16384.0f; // 2^14

    for (int y = 0; y < dst_h; y++) {
        int src_y = (int)(y * scale_y);
        if (src_y >= src_h) src_y = src_h - 1;
        for (int x = 0; x < dst_w; x++) {
            int src_x = (int)(x * scale_x);
            if (src_x >= src_w) src_x = src_w - 1;

            int idx = (src_y * src_w + src_x) * 2;
            uint16_t pixel = rgb565_buf[idx] | (rgb565_buf[idx + 1] << 8);
            uint8_t r = (pixel >> 11) & 0x1F;
            uint8_t g = (pixel >> 5) & 0x3F;
            uint8_t b = pixel & 0x1F;

            float rf = r * (255.0f / 31.0f);
            float gf = g * (255.0f / 63.0f);
            float bf = b * (255.0f / 31.0f);

            int dst_idx = (y * dst_w + x) * 3;
            dst[dst_idx + 0] = (int16_t)((rf / 127.5f - 1.0f) * quant_scale);
            dst[dst_idx + 1] = (int16_t)((gf / 127.5f - 1.0f) * quant_scale);
            dst[dst_idx + 2] = (int16_t)((bf / 127.5f - 1.0f) * quant_scale);
        }
    }
}

// ==================== 主程序 ====================

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Aesthetic Score - ESP32-S3-EYE ===");
    ESP_LOGI(TAG, "Free PSRAM: %d KB", heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024);

    // ===== 1. 初始化 LCD =====
    ESP_LOGI(TAG, "Init LCD...");
    lcd_init();
    ESP_LOGI(TAG, "LCD OK (240x240 ST7789)");

    // ===== 2. 初始化摄像头 =====
    ESP_LOGI(TAG, "Init camera...");
    camera_config_t cam_config = {};
    cam_config.pin_pwdn = CAM_PIN_PWDN;
    cam_config.pin_reset = CAM_PIN_RESET;
    cam_config.pin_xclk = CAM_PIN_XCLK;
    cam_config.pin_sccb_sda = CAM_PIN_SIOD;
    cam_config.pin_sccb_scl = CAM_PIN_SIOC;
    cam_config.pin_d7 = CAM_PIN_D7;
    cam_config.pin_d6 = CAM_PIN_D6;
    cam_config.pin_d5 = CAM_PIN_D5;
    cam_config.pin_d4 = CAM_PIN_D4;
    cam_config.pin_d3 = CAM_PIN_D3;
    cam_config.pin_d2 = CAM_PIN_D2;
    cam_config.pin_d1 = CAM_PIN_D1;
    cam_config.pin_d0 = CAM_PIN_D0;
    cam_config.pin_vsync = CAM_PIN_VSYNC;
    cam_config.pin_href = CAM_PIN_HREF;
    cam_config.pin_pclk = CAM_PIN_PCLK;
    cam_config.xclk_freq_hz = 16000000;
    cam_config.ledc_timer = LEDC_TIMER_0;
    cam_config.ledc_channel = LEDC_CHANNEL_0;
    cam_config.pixel_format = PIXFORMAT_RGB565;
    cam_config.frame_size = FRAMESIZE_240X240;  // 240x240 直接匹配 LCD
    cam_config.jpeg_quality = 12;
    cam_config.fb_count = 2;
    cam_config.fb_location = CAMERA_FB_IN_PSRAM;
    cam_config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;

    ESP_ERROR_CHECK(esp_camera_init(&cam_config));
    sensor_t *s = esp_camera_sensor_get();
    if (s) {
        s->set_vflip(s, 1);
        s->set_hmirror(s, 0);
    }
    ESP_LOGI(TAG, "Camera OK (240x240 RGB565)");

    // ===== 3. 加载模型 =====
    ESP_LOGI(TAG, "Loading model...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);

    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model load FAILED! Halting.");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    ESP_LOGI(TAG, "Model OK!");

    int16_t *model_input = (int16_t *)inputs.begin()->second->get_element_ptr();

    // ===== 4. 分配 LCD 显示缓冲区 =====
    // 用于叠加分数后发送到 LCD
    uint16_t *disp_buf = (uint16_t *)heap_caps_malloc(LCD_H_RES * LCD_V_RES * 2, MALLOC_CAP_SPIRAM);
    if (!disp_buf) {
        ESP_LOGE(TAG, "Failed to allocate display buffer");
        return;
    }

    // ===== 5. 主循环 =====
    ESP_LOGI(TAG, "Running! Camera → LCD + inference every 3s");
    float score = 0;
    int frame_count = 0;
    char score_text[16] = "-.--/10";

    while (1) {
        camera_fb_t *fb = esp_camera_fb_get();
        if (!fb) {
            vTaskDelay(pdMS_TO_TICKS(50));
            continue;
        }

        // 拷贝相机帧到显示缓冲区
        memcpy(disp_buf, fb->buf, LCD_H_RES * LCD_V_RES * 2);

        // 叠加分数文字（绿色，左上角，放大 3 倍）
        // RGB565 绿色 = 0x07E0
        uint16_t text_color = 0xE007; // swap bytes for LCD (big-endian)
        if (score >= 6.0f) text_color = 0xE007; // 绿
        else if (score >= 4.5f) text_color = 0xE0FF; // 黄
        else if (score > 0) text_color = 0x00F8; // 红

        draw_string_on_rgb565(disp_buf, LCD_H_RES, LCD_V_RES,
                              5, 5, score_text, text_color, 3);

        // 发送到 LCD
        esp_lcd_panel_draw_bitmap(lcd_panel, 0, 0, LCD_H_RES, LCD_V_RES, disp_buf);

        // 每 5 帧做一次推理
        frame_count++;
        if (frame_count % 5 == 0) {
            // 预处理
            preprocess_rgb565_to_int16(fb->buf, fb->width, fb->height,
                                        model_input, MODEL_W, MODEL_H);
            esp_camera_fb_return(fb);
            fb = NULL;

            // 推理
            int64_t t0 = esp_timer_get_time();
            model->run();
            int64_t dt = (esp_timer_get_time() - t0) / 1000;

            // 读取结果
            auto &outputs = model->get_outputs();
            if (!outputs.empty()) {
                auto out = outputs.begin()->second;
                int16_t *raw = (int16_t *)out->get_element_ptr();
                int exp = out->get_exponent();
                score = raw[0] * powf(2.0f, (float)exp);
                if (score < 1.0f) score = 1.0f;
                if (score > 10.0f) score = 10.0f;

                snprintf(score_text, sizeof(score_text), "%.1f/10", score);
                ESP_LOGI(TAG, "Score: %.2f (%lld ms)", score, dt);
            }
        } else {
            esp_camera_fb_return(fb);
        }

        vTaskDelay(pdMS_TO_TICKS(30));
    }
}

