/**
 * NIMA Aesthetic Score - ESP32-S3-EYE
 *
 * 使用 BSP 初始化 LCD（官方验证），esp32-camera 取图，esp-dl 推理
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "esp_lcd_panel_ops.h"
#include "esp_camera.h"
#include "bsp/esp-bsp.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima";

#define MODEL_W 224
#define MODEL_H 224
#define LCD_W   240
#define LCD_H   240

// ESP32-S3-EYE 相机引脚
#define CAM_PIN_XCLK    GPIO_NUM_15
#define CAM_PIN_SIOD    GPIO_NUM_4
#define CAM_PIN_SIOC    GPIO_NUM_5
#define CAM_PIN_D7      GPIO_NUM_16
#define CAM_PIN_D6      GPIO_NUM_17
#define CAM_PIN_D5      GPIO_NUM_18
#define CAM_PIN_D4      GPIO_NUM_12
#define CAM_PIN_D3      GPIO_NUM_10
#define CAM_PIN_D2      GPIO_NUM_8
#define CAM_PIN_D1      GPIO_NUM_9
#define CAM_PIN_D0      GPIO_NUM_11
#define CAM_PIN_VSYNC   GPIO_NUM_6
#define CAM_PIN_HREF    GPIO_NUM_7
#define CAM_PIN_PCLK    GPIO_NUM_13

// ==================== 预处理 ====================

static void preprocess_rgb565_to_int16(const uint8_t *rgb565_buf, int src_w, int src_h,
                                        int16_t *dst, int dst_w, int dst_h)
{
    const float scale_x = (float)src_w / dst_w;
    const float scale_y = (float)src_h / dst_h;
    const float quant_scale = 16384.0f;

    for (int y = 0; y < dst_h; y++) {
        int src_y = (int)(y * scale_y);
        if (src_y >= src_h) src_y = src_h - 1;
        for (int x = 0; x < dst_w; x++) {
            int src_x = (int)(x * scale_x);
            if (src_x >= src_w) src_x = src_w - 1;

            int idx = (src_y * src_w + src_x) * 2;
            uint16_t pixel = rgb565_buf[idx] | (rgb565_buf[idx + 1] << 8);
            uint8_t r = (pixel >> 11) & 0x1F;
            uint8_t g = (pixel >> 5) & 0x3F;
            uint8_t b = pixel & 0x1F;

            float rf = r * (255.0f / 31.0f);
            float gf = g * (255.0f / 63.0f);
            float bf = b * (255.0f / 31.0f);

            int dst_idx = (y * dst_w + x) * 3;
            dst[dst_idx + 0] = (int16_t)((rf / 127.5f - 1.0f) * quant_scale);
            dst[dst_idx + 1] = (int16_t)((gf / 127.5f - 1.0f) * quant_scale);
            dst[dst_idx + 2] = (int16_t)((bf / 127.5f - 1.0f) * quant_scale);
        }
    }
}

// ==================== 主程序 ====================

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Aesthetic Score - ESP32-S3-EYE ===");
    ESP_LOGI(TAG, "Free PSRAM: %d KB", heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024);

    // ===== 1. 使用 BSP 初始化 LCD（官方验证，保证能亮）=====
    ESP_LOGI(TAG, "Init LCD via BSP...");
    esp_lcd_panel_handle_t lcd_panel = NULL;
    esp_lcd_panel_io_handle_t lcd_io = NULL;
    const bsp_display_config_t disp_cfg = {
        .max_transfer_sz = LCD_W * LCD_H * 2,
    };
    ESP_ERROR_CHECK(bsp_display_new(&disp_cfg, &lcd_panel, &lcd_io));
    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(lcd_panel, true));
    bsp_display_backlight_on();
    ESP_LOGI(TAG, "LCD OK");

    // 测试：画一帧红色确认 LCD 能显示
    uint16_t *test_buf = (uint16_t *)heap_caps_malloc(LCD_W * 20 * 2, MALLOC_CAP_DMA | MALLOC_CAP_INTERNAL);
    if (test_buf) {
        for (int i = 0; i < LCD_W * 20; i++) test_buf[i] = 0x00F8; // 红色 (swap bytes)
        for (int y = 0; y < LCD_H; y += 20) {
            esp_lcd_panel_draw_bitmap(lcd_panel, 0, y, LCD_W, y + 20, test_buf);
        }
        ESP_LOGI(TAG, "LCD test: RED screen");
        vTaskDelay(pdMS_TO_TICKS(1000));
        free(test_buf);
    }

    // ===== 2. 初始化摄像头（手动配置，不用 BSP 的 camera API）=====
    ESP_LOGI(TAG, "Init camera...");
    camera_config_t cam_config = {};
    cam_config.pin_pwdn = (gpio_num_t)-1;
    cam_config.pin_reset = (gpio_num_t)-1;
    cam_config.pin_xclk = CAM_PIN_XCLK;
    cam_config.pin_sccb_sda = CAM_PIN_SIOD;
    cam_config.pin_sccb_scl = CAM_PIN_SIOC;
    cam_config.pin_d7 = CAM_PIN_D7;
    cam_config.pin_d6 = CAM_PIN_D6;
    cam_config.pin_d5 = CAM_PIN_D5;
    cam_config.pin_d4 = CAM_PIN_D4;
    cam_config.pin_d3 = CAM_PIN_D3;
    cam_config.pin_d2 = CAM_PIN_D2;
    cam_config.pin_d1 = CAM_PIN_D1;
    cam_config.pin_d0 = CAM_PIN_D0;
    cam_config.pin_vsync = CAM_PIN_VSYNC;
    cam_config.pin_href = CAM_PIN_HREF;
    cam_config.pin_pclk = CAM_PIN_PCLK;
    cam_config.xclk_freq_hz = 16000000;
    cam_config.ledc_timer = LEDC_TIMER_0;
    cam_config.ledc_channel = LEDC_CHANNEL_0;
    cam_config.pixel_format = PIXFORMAT_RGB565;
    cam_config.frame_size = FRAMESIZE_240X240;
    cam_config.jpeg_quality = 12;
    cam_config.fb_count = 2;
    cam_config.fb_location = CAMERA_FB_IN_PSRAM;
    cam_config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;

    esp_err_t cam_err = esp_camera_init(&cam_config);
    if (cam_err != ESP_OK) {
        ESP_LOGE(TAG, "Camera init failed: %s", esp_err_to_name(cam_err));
        // 相机失败也不退出，LCD 至少要显示错误
    } else {
        sensor_t *s = esp_camera_sensor_get();
        if (s) {
            s->set_vflip(s, 1);
            s->set_hmirror(s, 0);
        }
        ESP_LOGI(TAG, "Camera OK");
    }

    // ===== 3. 加载模型 =====
    ESP_LOGI(TAG, "Loading model...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model load FAILED!");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    int16_t *model_input = (int16_t *)inputs.begin()->second->get_element_ptr();
    ESP_LOGI(TAG, "Model OK");

    // ===== 4. 分配显示缓冲 =====
    // 用行缓冲方式刷屏（节省内存）
    uint16_t *line_buf = (uint16_t *)heap_caps_malloc(LCD_W * 20 * 2, MALLOC_CAP_DMA | MALLOC_CAP_INTERNAL);
    if (!line_buf) {
        ESP_LOGE(TAG, "Failed to alloc line buffer");
        return;
    }

    // ===== 5. 主循环 =====
    ESP_LOGI(TAG, "Running!");
    float score = 0;
    int frame_count = 0;

    while (1) {
        camera_fb_t *fb = esp_camera_fb_get();
        if (!fb) {
            vTaskDelay(pdMS_TO_TICKS(50));
            continue;
        }

        // 把相机帧逐块发送到 LCD（每次 20 行）
        for (int y = 0; y < LCD_H; y += 20) {
            int rows = 20;
            if (y + rows > LCD_H) rows = LCD_H - y;
            // 相机帧 RGB565 直接拷贝到 line buffer
            memcpy(line_buf, fb->buf + y * LCD_W * 2, LCD_W * rows * 2);
            esp_lcd_panel_draw_bitmap(lcd_panel, 0, y, LCD_W, y + rows, line_buf);
        }

        // 每 5 帧做一次推理
        frame_count++;
        if (frame_count % 5 == 0) {
            preprocess_rgb565_to_int16(fb->buf, fb->width, fb->height,
                                        model_input, MODEL_W, MODEL_H);
            esp_camera_fb_return(fb);
            fb = NULL;

            int64_t t0 = esp_timer_get_time();
            model->run();
            int64_t dt = (esp_timer_get_time() - t0) / 1000;

            auto &outputs = model->get_outputs();
            if (!outputs.empty()) {
                auto out = outputs.begin()->second;
                int16_t *raw = (int16_t *)out->get_element_ptr();
                int exp = out->get_exponent();
                score = raw[0] * powf(2.0f, (float)exp);
                if (score < 1.0f) score = 1.0f;
                if (score > 10.0f) score = 10.0f;
                ESP_LOGI(TAG, "Score: %.2f (%lld ms)", score, dt);
            }
        } else {
            esp_camera_fb_return(fb);
        }

        vTaskDelay(pdMS_TO_TICKS(30));
    }
}

/**
 * NIMA Aesthetic Score - ESP32-S3-EYE
 *
 * 模式：实时相机预览 + 按键拍照评分
 * - 平时：流畅的实时相机预览
 * - 按 BOOT 键：拍照 → 推理 → 显示分数 3 秒 → 恢复预览
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "esp_lcd_panel_ops.h"
#include "esp_camera.h"
#include "driver/gpio.h"
#include "bsp/esp-bsp.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima";

#define MODEL_W 224
#define MODEL_H 224
#define LCD_W   240
#define LCD_H   240

// BOOT 按键 (GPIO 0) - 按下为低电平
#define BTN_SHUTTER GPIO_NUM_0

// ESP32-S3-EYE 相机引脚
#define CAM_PIN_XCLK    GPIO_NUM_15
#define CAM_PIN_SIOD    GPIO_NUM_4
#define CAM_PIN_SIOC    GPIO_NUM_5
#define CAM_PIN_D7      GPIO_NUM_16
#define CAM_PIN_D6      GPIO_NUM_17
#define CAM_PIN_D5      GPIO_NUM_18
#define CAM_PIN_D4      GPIO_NUM_12
#define CAM_PIN_D3      GPIO_NUM_10
#define CAM_PIN_D2      GPIO_NUM_8
#define CAM_PIN_D1      GPIO_NUM_9
#define CAM_PIN_D0      GPIO_NUM_11
#define CAM_PIN_VSYNC   GPIO_NUM_6
#define CAM_PIN_HREF    GPIO_NUM_7
#define CAM_PIN_PCLK    GPIO_NUM_13

// ==================== 简易字体（5x7 像素） ====================

static const uint8_t font_5x7[][7] = {
    {0x0E,0x11,0x13,0x15,0x19,0x11,0x0E}, // 0
    {0x04,0x0C,0x04,0x04,0x04,0x04,0x0E}, // 1
    {0x0E,0x11,0x01,0x06,0x08,0x10,0x1F}, // 2
    {0x0E,0x11,0x01,0x06,0x01,0x11,0x0E}, // 3
    {0x02,0x06,0x0A,0x12,0x1F,0x02,0x02}, // 4
    {0x1F,0x10,0x1E,0x01,0x01,0x11,0x0E}, // 5
    {0x06,0x08,0x10,0x1E,0x11,0x11,0x0E}, // 6
    {0x1F,0x01,0x02,0x04,0x08,0x08,0x08}, // 7
    {0x0E,0x11,0x11,0x0E,0x11,0x11,0x0E}, // 8
    {0x0E,0x11,0x11,0x0F,0x01,0x02,0x0C}, // 9
    {0x00,0x00,0x00,0x00,0x00,0x00,0x04}, // '.' = 10
    {0x01,0x02,0x02,0x04,0x08,0x08,0x10}, // '/' = 11
    {0x00,0x00,0x00,0x00,0x00,0x00,0x00}, // ' ' = 12
};

static int char_to_idx(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c == '.') return 10;
    if (c == '/') return 11;
    return 12;
}

// 在 RGB565 buffer 上画文字（带黑色背景框）
static void draw_text(uint16_t *buf, int bw, int bh,
                      int sx, int sy, const char *str,
                      uint16_t fg, int scale)
{
    int len = strlen(str);
    int text_w = len * 6 * scale;
    int text_h = 7 * scale;

    // 画半透明黑色背景
    for (int py = sy - 2; py < sy + text_h + 2 && py < bh; py++) {
        if (py < 0) continue;
        for (int px = sx - 2; px < sx + text_w + 2 && px < bw; px++) {
            if (px < 0) continue;
            // 简单变暗：右移每个通道
            uint16_t orig = buf[py * bw + px];
            uint16_t dark = ((orig >> 1) & 0x7BEF); // 每通道除以2
            buf[py * bw + px] = dark;
        }
    }

    // 画文字
    int cx = sx;
    for (int i = 0; str[i]; i++) {
        int fi = char_to_idx(str[i]);
        for (int row = 0; row < 7; row++) {
            uint8_t bits = font_5x7[fi][row];
            for (int col = 0; col < 5; col++) {
                if (bits & (0x10 >> col)) {
                    for (int sy2 = 0; sy2 < scale; sy2++) {
                        for (int sx2 = 0; sx2 < scale; sx2++) {
                            int px = cx + col * scale + sx2;
                            int py = sy + row * scale + sy2;
                            if (px < bw && py < bh)
                                buf[py * bw + px] = fg;
                        }
                    }
                }
            }
        }
        cx += 6 * scale;
    }
}

// ==================== 预处理 ====================

static void preprocess(const uint8_t *rgb565, int sw, int sh,
                       int16_t *dst, int dw, int dh)
{
    float sx = (float)sw / dw, sy = (float)sh / dh;
    for (int y = 0; y < dh; y++) {
        int src_y = (int)(y * sy);
        if (src_y >= sh) src_y = sh - 1;
        for (int x = 0; x < dw; x++) {
            int src_x = (int)(x * sx);
            if (src_x >= sw) src_x = sw - 1;
            int idx = (src_y * sw + src_x) * 2;
            uint16_t p = rgb565[idx] | (rgb565[idx + 1] << 8);
            float r = ((p >> 11) & 0x1F) * (255.0f / 31.0f);
            float g = ((p >> 5) & 0x3F) * (255.0f / 63.0f);
            float b = (p & 0x1F) * (255.0f / 31.0f);
            int di = (y * dw + x) * 3;
            dst[di + 0] = (int16_t)((r / 127.5f - 1.0f) * 16384.0f);
            dst[di + 1] = (int16_t)((g / 127.5f - 1.0f) * 16384.0f);
            dst[di + 2] = (int16_t)((b / 127.5f - 1.0f) * 16384.0f);
        }
    }
}

// ==================== 主程序 ====================

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Selfie Score - ESP32-S3-EYE ===");

    // ===== 按键初始化 =====
    gpio_config_t btn_cfg = {};
    btn_cfg.pin_bit_mask = (1ULL << BTN_SHUTTER);
    btn_cfg.mode = GPIO_MODE_INPUT;
    btn_cfg.pull_up_en = GPIO_PULLUP_ENABLE;
    gpio_config(&btn_cfg);

    // ===== LCD 初始化（BSP 官方） =====
    ESP_LOGI(TAG, "Init LCD...");
    esp_lcd_panel_handle_t lcd = NULL;
    esp_lcd_panel_io_handle_t lcd_io = NULL;
    const bsp_display_config_t disp_cfg = { .max_transfer_sz = LCD_W * LCD_H * 2 };
    ESP_ERROR_CHECK(bsp_display_new(&disp_cfg, &lcd, &lcd_io));
    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(lcd, true));
    bsp_display_backlight_on();
    ESP_LOGI(TAG, "LCD OK");

    // ===== 摄像头初始化 =====
    ESP_LOGI(TAG, "Init camera...");
    camera_config_t cam = {};
    cam.pin_pwdn = (gpio_num_t)-1;
    cam.pin_reset = (gpio_num_t)-1;
    cam.pin_xclk = CAM_PIN_XCLK;
    cam.pin_sccb_sda = CAM_PIN_SIOD;
    cam.pin_sccb_scl = CAM_PIN_SIOC;
    cam.pin_d7 = CAM_PIN_D7; cam.pin_d6 = CAM_PIN_D6;
    cam.pin_d5 = CAM_PIN_D5; cam.pin_d4 = CAM_PIN_D4;
    cam.pin_d3 = CAM_PIN_D3; cam.pin_d2 = CAM_PIN_D2;
    cam.pin_d1 = CAM_PIN_D1; cam.pin_d0 = CAM_PIN_D0;
    cam.pin_vsync = CAM_PIN_VSYNC;
    cam.pin_href = CAM_PIN_HREF;
    cam.pin_pclk = CAM_PIN_PCLK;
    cam.xclk_freq_hz = 16000000;
    cam.ledc_timer = LEDC_TIMER_0;
    cam.ledc_channel = LEDC_CHANNEL_0;
    cam.pixel_format = PIXFORMAT_RGB565;
    cam.frame_size = FRAMESIZE_240X240;
    cam.fb_count = 2;
    cam.fb_location = CAMERA_FB_IN_PSRAM;
    cam.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
    ESP_ERROR_CHECK(esp_camera_init(&cam));
    sensor_t *s = esp_camera_sensor_get();
    if (s) { s->set_vflip(s, 1); s->set_hmirror(s, 0); }
    ESP_LOGI(TAG, "Camera OK");

    // ===== 模型加载 =====
    ESP_LOGI(TAG, "Loading model...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model FAILED");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    int16_t *model_input = (int16_t *)inputs.begin()->second->get_element_ptr();
    ESP_LOGI(TAG, "Model OK");

    // ===== 行缓冲（用于 LCD 刷新）=====
    const int CHUNK = 20; // 每次刷 20 行
    uint16_t *line_buf = (uint16_t *)heap_caps_malloc(LCD_W * CHUNK * 2, MALLOC_CAP_DMA | MALLOC_CAP_INTERNAL);

    ESP_LOGI(TAG, "Ready! Press BOOT button to score a photo.");

    // ===== 主循环 =====
    bool show_score = false;
    int score_display_countdown = 0;
    float last_score = 0;
    char score_str[32] = "";

    while (1) {
        // 检测按键（低电平 = 按下）
        bool btn_pressed = (gpio_get_level(BTN_SHUTTER) == 0);

        if (btn_pressed && !show_score) {
            // ===== 拍照 + 评分 =====
            ESP_LOGI(TAG, "SNAP! Scoring...");

            camera_fb_t *fb = esp_camera_fb_get();
            if (fb) {
                // 预处理
                preprocess(fb->buf, fb->width, fb->height, model_input, MODEL_W, MODEL_H);

                // 在冻结画面上画"评分中..."提示
                // 先完整显示这一帧到 LCD
                for (int y = 0; y < LCD_H; y += CHUNK) {
                    int rows = (y + CHUNK > LCD_H) ? LCD_H - y : CHUNK;
                    memcpy(line_buf, fb->buf + y * LCD_W * 2, LCD_W * rows * 2);
                    esp_lcd_panel_draw_bitmap(lcd, 0, y, LCD_W, y + rows, line_buf);
                }
                esp_camera_fb_return(fb);

                // 推理
                int64_t t0 = esp_timer_get_time();
                model->run();
                int64_t dt = (esp_timer_get_time() - t0) / 1000;

                // 获取分数
                auto &outputs = model->get_outputs();
                if (!outputs.empty()) {
                    auto out = outputs.begin()->second;
                    int16_t *raw = (int16_t *)out->get_element_ptr();
                    int exp = out->get_exponent();
                    last_score = raw[0] * powf(2.0f, (float)exp);
                    if (last_score < 1.0f) last_score = 1.0f;
                    if (last_score > 10.0f) last_score = 10.0f;
                    snprintf(score_str, sizeof(score_str), "%.1f/10", last_score);
                    ESP_LOGI(TAG, "Score: %.2f (%lld ms)", last_score, dt);
                }

                // 重新取一帧带分数显示
                fb = esp_camera_fb_get();
                if (fb) {
                    // 把整帧拷贝到 PSRAM 缓冲用于叠加文字
                    uint16_t *frame = (uint16_t *)heap_caps_malloc(LCD_W * LCD_H * 2, MALLOC_CAP_SPIRAM);
                    if (frame) {
                        memcpy(frame, fb->buf, LCD_W * LCD_H * 2);
                        esp_camera_fb_return(fb);

                        // 在帧上画分数
                        uint16_t color = 0x07E0; // 绿
                        if (last_score < 4.5f) color = 0xF800; // 红
                        else if (last_score < 6.0f) color = 0xFFE0; // 黄
                        draw_text(frame, LCD_W, LCD_H, 10, 10, score_str, color, 4);

                        // 显示到 LCD
                        for (int y = 0; y < LCD_H; y += CHUNK) {
                            int rows = (y + CHUNK > LCD_H) ? LCD_H - y : CHUNK;
                            memcpy(line_buf, (uint8_t*)frame + y * LCD_W * 2, LCD_W * rows * 2);
                            esp_lcd_panel_draw_bitmap(lcd, 0, y, LCD_W, y + rows, line_buf);
                        }
                        free(frame);
                    } else {
                        esp_camera_fb_return(fb);
                    }
                }

                show_score = true;
                score_display_countdown = 60; // 约 3 秒 (60 * 50ms)
            }

            // 等待按键释放（消抖）
            while (gpio_get_level(BTN_SHUTTER) == 0) {
                vTaskDelay(pdMS_TO_TICKS(20));
            }
            vTaskDelay(pdMS_TO_TICKS(100));

        } else if (show_score) {
            // ===== 显示分数期间：画面冻结 =====
            score_display_countdown--;
            if (score_display_countdown <= 0) {
                show_score = false;
                ESP_LOGI(TAG, "Back to preview");
            }
            vTaskDelay(pdMS_TO_TICKS(50));

        } else {
            // ===== 正常预览模式：流畅刷新 =====
            camera_fb_t *fb = esp_camera_fb_get();
            if (fb) {
                for (int y = 0; y < LCD_H; y += CHUNK) {
                    int rows = (y + CHUNK > LCD_H) ? LCD_H - y : CHUNK;
                    memcpy(line_buf, fb->buf + y * LCD_W * 2, LCD_W * rows * 2);
                    esp_lcd_panel_draw_bitmap(lcd, 0, y, LCD_W, y + rows, line_buf);
                }
                esp_camera_fb_return(fb);
            }
            vTaskDelay(pdMS_TO_TICKS(10));
        }
    }
}

