/**
 * NIMA Aesthetic Score - ESP32-S3-EYE
 *
 * 模式：实时相机预览 + 按键拍照评分
 * - 平时：流畅的实时相机预览
 * - 按 BOOT 键：拍照 → 推理 → 显示分数 3 秒 → 恢复预览
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "esp_lcd_panel_ops.h"
#include "esp_camera.h"
#include "driver/gpio.h"
#include "bsp/esp-bsp.h"
#include "dl_model_base.hpp"

static const char *TAG = "nima";

#define MODEL_W 224
#define MODEL_H 224
#define LCD_W   240
#define LCD_H   240

// BOOT 按键 (GPIO 0) - 按下为低电平
#define BTN_SHUTTER GPIO_NUM_0

// ESP32-S3-EYE 相机引脚
#define CAM_PIN_XCLK    GPIO_NUM_15
#define CAM_PIN_SIOD    GPIO_NUM_4
#define CAM_PIN_SIOC    GPIO_NUM_5
#define CAM_PIN_D7      GPIO_NUM_16
#define CAM_PIN_D6      GPIO_NUM_17
#define CAM_PIN_D5      GPIO_NUM_18
#define CAM_PIN_D4      GPIO_NUM_12
#define CAM_PIN_D3      GPIO_NUM_10
#define CAM_PIN_D2      GPIO_NUM_8
#define CAM_PIN_D1      GPIO_NUM_9
#define CAM_PIN_D0      GPIO_NUM_11
#define CAM_PIN_VSYNC   GPIO_NUM_6
#define CAM_PIN_HREF    GPIO_NUM_7
#define CAM_PIN_PCLK    GPIO_NUM_13

// ==================== 简易字体（5x7） ====================

static const uint8_t font_5x7[][7] = {
    {0x0E,0x11,0x13,0x15,0x19,0x11,0x0E}, // 0
    {0x04,0x0C,0x04,0x04,0x04,0x04,0x0E}, // 1
    {0x0E,0x11,0x01,0x06,0x08,0x10,0x1F}, // 2
    {0x0E,0x11,0x01,0x06,0x01,0x11,0x0E}, // 3
    {0x02,0x06,0x0A,0x12,0x1F,0x02,0x02}, // 4
    {0x1F,0x10,0x1E,0x01,0x01,0x11,0x0E}, // 5
    {0x06,0x08,0x10,0x1E,0x11,0x11,0x0E}, // 6
    {0x1F,0x01,0x02,0x04,0x08,0x08,0x08}, // 7
    {0x0E,0x11,0x11,0x0E,0x11,0x11,0x0E}, // 8
    {0x0E,0x11,0x11,0x0F,0x01,0x02,0x0C}, // 9
    {0x00,0x00,0x00,0x00,0x00,0x00,0x04}, // '.' = 10
    {0x01,0x02,0x02,0x04,0x08,0x08,0x10}, // '/' = 11
    {0x00,0x00,0x00,0x00,0x00,0x00,0x00}, // ' ' = 12
};

static int char_to_idx(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c == '.') return 10;
    if (c == '/') return 11;
    return 12;
}

// 在 RGB565 buffer 上画文字（scale=倍数）
static void draw_text(uint16_t *buf, int bw, int bh,
                      int sx, int sy, const char *str,
                      uint16_t fg, int scale)
{
    int cx = sx;
    for (int i = 0; str[i]; i++) {
        int fi = char_to_idx(str[i]);
        for (int row = 0; row < 7; row++) {
            uint8_t bits = font_5x7[fi][row];
            for (int col = 0; col < 5; col++) {
                if (bits & (0x10 >> col)) {
                    for (int sy2 = 0; sy2 < scale; sy2++) {
                        for (int sx2 = 0; sx2 < scale; sx2++) {
                            int px = cx + col * scale + sx2;
                            int py = sy + row * scale + sy2;
                            if (px >= 0 && px < bw && py >= 0 && py < bh) {
                                buf[py * bw + px] = fg;
                            }
                        }
                    }
                }
            }
        }
        cx += 6 * scale;
    }
}

// ==================== 预处理 ====================

static void preprocess(const uint8_t *rgb565, int sw, int sh,
                       int16_t *dst, int dw, int dh)
{
    float scx = (float)sw / dw, scy = (float)sh / dh;
    for (int y = 0; y < dh; y++) {
        int src_y = (int)(y * scy);
        if (src_y >= sh) src_y = sh - 1;
        for (int x = 0; x < dw; x++) {
            int src_x = (int)(x * scx);
            if (src_x >= sw) src_x = sw - 1;
            int idx = (src_y * sw + src_x) * 2;
            // esp32-camera RGB565 输出: byte0=高字节 byte1=低字节 (大端)
            uint16_t p = (rgb565[idx] << 8) | rgb565[idx + 1];
            float r = ((p >> 11) & 0x1F) * (255.0f / 31.0f);
            float g = ((p >> 5) & 0x3F) * (255.0f / 63.0f);
            float b = (p & 0x1F) * (255.0f / 31.0f);
            int di = (y * dw + x) * 3;
            dst[di + 0] = (int16_t)((r / 127.5f - 1.0f) * 16384.0f);
            dst[di + 1] = (int16_t)((g / 127.5f - 1.0f) * 16384.0f);
            dst[di + 2] = (int16_t)((b / 127.5f - 1.0f) * 16384.0f);
        }
    }
}

// ==================== LCD 显示一帧 ====================

static void lcd_show_frame(esp_lcd_panel_handle_t lcd, const void *buf)
{
    // 直接一次性推整帧到 LCD
    esp_lcd_panel_draw_bitmap(lcd, 0, 0, LCD_W, LCD_H, buf);
}

// ==================== 主程序 ====================

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== NIMA Selfie Score - ESP32-S3-EYE ===");

    // ===== 按键初始化 =====
    gpio_config_t btn_cfg = {};
    btn_cfg.pin_bit_mask = (1ULL << BTN_SHUTTER);
    btn_cfg.mode = GPIO_MODE_INPUT;
    btn_cfg.pull_up_en = GPIO_PULLUP_ENABLE;
    gpio_config(&btn_cfg);

    // ===== LCD 初始化（BSP 官方） =====
    ESP_LOGI(TAG, "Init LCD...");
    esp_lcd_panel_handle_t lcd = NULL;
    esp_lcd_panel_io_handle_t lcd_io = NULL;
    const bsp_display_config_t disp_cfg = { .max_transfer_sz = LCD_W * LCD_H * 2 };
    ESP_ERROR_CHECK(bsp_display_new(&disp_cfg, &lcd, &lcd_io));
    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(lcd, true));
    bsp_display_backlight_on();
    ESP_LOGI(TAG, "LCD OK");

    // ===== 摄像头初始化 =====
    ESP_LOGI(TAG, "Init camera...");
    camera_config_t cam_cfg = {};
    cam_cfg.pin_pwdn = (gpio_num_t)-1;
    cam_cfg.pin_reset = (gpio_num_t)-1;
    cam_cfg.pin_xclk = CAM_PIN_XCLK;
    cam_cfg.pin_sccb_sda = CAM_PIN_SIOD;
    cam_cfg.pin_sccb_scl = CAM_PIN_SIOC;
    cam_cfg.pin_d7 = CAM_PIN_D7; cam_cfg.pin_d6 = CAM_PIN_D6;
    cam_cfg.pin_d5 = CAM_PIN_D5; cam_cfg.pin_d4 = CAM_PIN_D4;
    cam_cfg.pin_d3 = CAM_PIN_D3; cam_cfg.pin_d2 = CAM_PIN_D2;
    cam_cfg.pin_d1 = CAM_PIN_D1; cam_cfg.pin_d0 = CAM_PIN_D0;
    cam_cfg.pin_vsync = CAM_PIN_VSYNC;
    cam_cfg.pin_href = CAM_PIN_HREF;
    cam_cfg.pin_pclk = CAM_PIN_PCLK;
    cam_cfg.xclk_freq_hz = 16000000;
    cam_cfg.ledc_timer = LEDC_TIMER_0;
    cam_cfg.ledc_channel = LEDC_CHANNEL_0;
    cam_cfg.pixel_format = PIXFORMAT_RGB565;
    cam_cfg.frame_size = FRAMESIZE_240X240;
    cam_cfg.fb_count = 2;
    cam_cfg.fb_location = CAMERA_FB_IN_PSRAM;
    cam_cfg.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
    ESP_ERROR_CHECK(esp_camera_init(&cam_cfg));
    sensor_t *s = esp_camera_sensor_get();
    if (s) { s->set_vflip(s, 1); s->set_hmirror(s, 0); }
    ESP_LOGI(TAG, "Camera OK");

    // ===== 模型加载 =====
    ESP_LOGI(TAG, "Loading model...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model FAILED");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    int16_t *model_input = (int16_t *)inputs.begin()->second->get_element_ptr();
    ESP_LOGI(TAG, "Model OK");

    ESP_LOGI(TAG, "Ready! Press BOOT button to score.");

    // ===== 主循环 =====
    bool showing_score = false;
    int countdown = 0;

    while (1) {
        bool btn = (gpio_get_level(BTN_SHUTTER) == 0);

        if (btn && !showing_score) {
            // ======= 拍照评分 =======
            ESP_LOGI(TAG, "SNAP!");
            camera_fb_t *fb = esp_camera_fb_get();
            if (!fb) { vTaskDelay(pdMS_TO_TICKS(50)); continue; }

            // 预处理用于推理
            preprocess(fb->buf, fb->width, fb->height, model_input, MODEL_W, MODEL_H);

            // 显示拍摄画面
            lcd_show_frame(lcd, fb->buf);
            esp_camera_fb_return(fb);

            // 推理
            int64_t t0 = esp_timer_get_time();
            model->run();
            int64_t dt = (esp_timer_get_time() - t0) / 1000;

            // 获取分数
            float score = 5.0f;
            auto &outputs = model->get_outputs();
            if (!outputs.empty()) {
                auto out = outputs.begin()->second;
                int16_t *raw = (int16_t *)out->get_element_ptr();
                int exp_val = out->get_exponent();
                score = raw[0] * powf(2.0f, (float)exp_val);
                if (score < 1.0f) score = 1.0f;
                if (score > 10.0f) score = 10.0f;
            }
            ESP_LOGI(TAG, "Score: %.2f (%lld ms)", score, dt);

            // 在 PSRAM 中创建帧副本，叠加分数后显示
            uint16_t *overlay = (uint16_t *)heap_caps_malloc(LCD_W * LCD_H * 2, MALLOC_CAP_SPIRAM);
            if (overlay) {
                // 重新取一帧作为展示底图
                fb = esp_camera_fb_get();
                if (fb) {
                    memcpy(overlay, fb->buf, LCD_W * LCD_H * 2);
                    esp_camera_fb_return(fb);
                } else {
                    memset(overlay, 0, LCD_W * LCD_H * 2);
                }

                // 画分数文字
                char txt[16];
                snprintf(txt, sizeof(txt), "%.1f/10", score);
                uint16_t color;
                if (score >= 6.0f) color = 0xE007;       // 绿 (big-endian 0x07E0)
                else if (score >= 4.5f) color = 0xE0FF;  // 黄 (big-endian 0xFFE0)
                else color = 0x00F8;                      // 红 (big-endian 0xF800)
                draw_text(overlay, LCD_W, LCD_H, 8, 8, txt, color, 4);

                // 推到 LCD
                lcd_show_frame(lcd, overlay);
                free(overlay);
            }

            showing_score = true;
            countdown = 60;

            // 等按键释放
            while (gpio_get_level(BTN_SHUTTER) == 0) vTaskDelay(pdMS_TO_TICKS(20));
            vTaskDelay(pdMS_TO_TICKS(100));

        } else if (showing_score) {
            // ======= 展示分数倒计时 =======
            countdown--;
            if (countdown <= 0) {
                showing_score = false;
                ESP_LOGI(TAG, "Back to preview");
            }
            vTaskDelay(pdMS_TO_TICKS(50));

        } else {
            // ======= 实时预览 =======
            camera_fb_t *fb = esp_camera_fb_get();
            if (fb) {
                lcd_show_frame(lcd, fb->buf);
                esp_camera_fb_return(fb);
            }
            vTaskDelay(pdMS_TO_TICKS(10));
        }
    }
}

/**
 * YOLOX-Nano 目标检测 - ESP32-S3-EYE
 *
 * 模式：实时相机预览 + 按键拍照检测
 * - 平时：流畅实时预览
 * - 按 BOOT 键：拍照 → 推理 → 串口输出检测结果 → 恢复预览
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "esp_lcd_panel_ops.h"
#include "esp_camera.h"
#include "driver/gpio.h"
#include "bsp/esp-bsp.h"
#include "dl_model_base.hpp"

static const char *TAG = "yolox";

// YOLOX-Nano 模型参数
#define MODEL_W 416
#define MODEL_H 416
#define MODEL_C 3
#define LCD_W   240
#define LCD_H   240

// BOOT 按键
#define BTN_SHUTTER GPIO_NUM_0

// ESP32-S3-EYE 相机引脚
#define CAM_PIN_XCLK    GPIO_NUM_15
#define CAM_PIN_SIOD    GPIO_NUM_4
#define CAM_PIN_SIOC    GPIO_NUM_5
#define CAM_PIN_D7      GPIO_NUM_16
#define CAM_PIN_D6      GPIO_NUM_17
#define CAM_PIN_D5      GPIO_NUM_18
#define CAM_PIN_D4      GPIO_NUM_12
#define CAM_PIN_D3      GPIO_NUM_10
#define CAM_PIN_D2      GPIO_NUM_8
#define CAM_PIN_D1      GPIO_NUM_9
#define CAM_PIN_D0      GPIO_NUM_11
#define CAM_PIN_VSYNC   GPIO_NUM_6
#define CAM_PIN_HREF    GPIO_NUM_7
#define CAM_PIN_PCLK    GPIO_NUM_13

// ==================== 预处理 ====================

/**
 * RGB565 (240x240) → NCHW int8 (3x416x416)
 * YOLOX 预处理：像素值 0-255 直接量化为 int8
 * 模型输入 exponent 通常是 0 或由模型决定
 */
static void preprocess_rgb565_to_int8_nchw(const uint8_t *rgb565, int sw, int sh,
                                            int8_t *dst, int dw, int dh)
{
    float scx = (float)sw / dw;
    float scy = (float)sh / dh;

    // NCHW: dst[c * H * W + y * W + x]
    int plane_size = dw * dh;

    for (int y = 0; y < dh; y++) {
        int src_y = (int)(y * scy);
        if (src_y >= sh) src_y = sh - 1;
        for (int x = 0; x < dw; x++) {
            int src_x = (int)(x * scx);
            if (src_x >= sw) src_x = sw - 1;

            int idx = (src_y * sw + src_x) * 2;
            // esp32-camera RGB565 大端
            uint16_t p = (rgb565[idx] << 8) | rgb565[idx + 1];
            uint8_t r = ((p >> 11) & 0x1F) * 255 / 31;
            uint8_t g = ((p >> 5) & 0x3F) * 255 / 63;
            uint8_t b = (p & 0x1F) * 255 / 31;

            // 量化为 int8: val - 128 (对称量化，0-255 映射到 -128~127)
            dst[0 * plane_size + y * dw + x] = (int8_t)(r - 128);
            dst[1 * plane_size + y * dw + x] = (int8_t)(g - 128);
            dst[2 * plane_size + y * dw + x] = (int8_t)(b - 128);
        }
    }
}

// ==================== LCD 显示 ====================

static void lcd_show_frame(esp_lcd_panel_handle_t lcd, const void *buf)
{
    esp_lcd_panel_draw_bitmap(lcd, 0, 0, LCD_W, LCD_H, buf);
}

// ==================== 主程序 ====================

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== YOLOX-Nano Detection - ESP32-S3-EYE ===");
    ESP_LOGI(TAG, "Free PSRAM: %d KB", heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024);

    // ===== 按键 =====
    gpio_config_t btn_cfg = {};
    btn_cfg.pin_bit_mask = (1ULL << BTN_SHUTTER);
    btn_cfg.mode = GPIO_MODE_INPUT;
    btn_cfg.pull_up_en = GPIO_PULLUP_ENABLE;
    gpio_config(&btn_cfg);

    // ===== LCD（BSP）=====
    ESP_LOGI(TAG, "Init LCD...");
    esp_lcd_panel_handle_t lcd = NULL;
    esp_lcd_panel_io_handle_t lcd_io = NULL;
    const bsp_display_config_t disp_cfg = { .max_transfer_sz = LCD_W * LCD_H * 2 };
    ESP_ERROR_CHECK(bsp_display_new(&disp_cfg, &lcd, &lcd_io));
    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(lcd, true));
    bsp_display_backlight_on();
    ESP_LOGI(TAG, "LCD OK");

    // ===== 摄像头 =====
    ESP_LOGI(TAG, "Init camera...");
    camera_config_t cam_cfg = {};
    cam_cfg.pin_pwdn = (gpio_num_t)-1;
    cam_cfg.pin_reset = (gpio_num_t)-1;
    cam_cfg.pin_xclk = CAM_PIN_XCLK;
    cam_cfg.pin_sccb_sda = CAM_PIN_SIOD;
    cam_cfg.pin_sccb_scl = CAM_PIN_SIOC;
    cam_cfg.pin_d7 = CAM_PIN_D7; cam_cfg.pin_d6 = CAM_PIN_D6;
    cam_cfg.pin_d5 = CAM_PIN_D5; cam_cfg.pin_d4 = CAM_PIN_D4;
    cam_cfg.pin_d3 = CAM_PIN_D3; cam_cfg.pin_d2 = CAM_PIN_D2;
    cam_cfg.pin_d1 = CAM_PIN_D1; cam_cfg.pin_d0 = CAM_PIN_D0;
    cam_cfg.pin_vsync = CAM_PIN_VSYNC;
    cam_cfg.pin_href = CAM_PIN_HREF;
    cam_cfg.pin_pclk = CAM_PIN_PCLK;
    cam_cfg.xclk_freq_hz = 16000000;
    cam_cfg.ledc_timer = LEDC_TIMER_0;
    cam_cfg.ledc_channel = LEDC_CHANNEL_0;
    cam_cfg.pixel_format = PIXFORMAT_RGB565;
    cam_cfg.frame_size = FRAMESIZE_240X240;
    cam_cfg.fb_count = 2;
    cam_cfg.fb_location = CAMERA_FB_IN_PSRAM;
    cam_cfg.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
    ESP_ERROR_CHECK(esp_camera_init(&cam_cfg));
    sensor_t *s = esp_camera_sensor_get();
    if (s) { s->set_vflip(s, 1); s->set_hmirror(s, 0); }
    ESP_LOGI(TAG, "Camera OK");

    // ===== 模型加载 =====
    ESP_LOGI(TAG, "Loading YOLOX-Nano model...");
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model FAILED to load!");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    ESP_LOGI(TAG, "Model loaded! Input size: %d elements", inputs.begin()->second->get_size());

    // 打印模型信息
    model->profile_memory();

    // ===== 主循环 =====
    ESP_LOGI(TAG, "Ready! Press BOOT to detect objects.");
    bool showing_result = false;
    int countdown = 0;

    while (1) {
        bool btn = (gpio_get_level(BTN_SHUTTER) == 0);

        if (btn && !showing_result) {
            // ======= 拍照 + 检测 =======
            ESP_LOGI(TAG, "SNAP! Running detection...");
