                    int n = tensor->get_size() < 20 ? tensor->get_size() : 20;
                    printf("  First %d values: ", n);
                    for (int i = 0; i < n; i++) printf("%d ", data[i]);
                    printf("\n");
                }
            }

            ESP_LOGI(TAG, "Free heap: %lu, PSRAM: %d",
                     esp_get_free_heap_size(),
                     heap_caps_get_free_size(MALLOC_CAP_SPIRAM));

            showing_result = true;
            countdown = 60;

            while (gpio_get_level(BTN_SHUTTER) == 0) vTaskDelay(pdMS_TO_TICKS(20));
            vTaskDelay(pdMS_TO_TICKS(100));

        } else if (showing_result) {
            countdown--;
            if (countdown <= 0) {
                showing_result = false;
                ESP_LOGI(TAG, "Back to preview");
            }
            vTaskDelay(pdMS_TO_TICKS(50));

        } else {
            // ======= 实时预览 =======
            camera_fb_t *fb = esp_camera_fb_get();
            if (fb) {
                lcd_show_frame(lcd, fb->buf);
                esp_camera_fb_return(fb);
            }
            vTaskDelay(pdMS_TO_TICKS(10));
        }
    }
}

