input.text:
/**
 * YOLOX-Nano 目标检测 - ESP32-S3-EYE (完全独立运行)
 *
 * 实时预览 → 按 BOOT 键拍照 → 检测 → LCD 上画框+类别 → 3 秒后恢复
 * 不需要连接电脑，所有结果在 LCD 上显示
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "esp_lcd_panel_ops.h"
#include "esp_camera.h"
#include "driver/gpio.h"
#include "bsp/esp-bsp.h"
#include "dl_model_base.hpp"

static const char *TAG = "yolox";

#define MODEL_W 416
#define MODEL_H 416
#define LCD_W   240
#define LCD_H   240
#define NUM_CLASSES 80
#define NUM_BOXES   3549  // YOLOX-Nano 输出 3549 个候选框
#define BOX_DIM     85    // 4(bbox) + 1(obj) + 80(class)
#define CONF_THRESH 0.3f
#define NMS_THRESH  0.45f
#define MAX_DET     10    // 最多显示 10 个检测结果

#define BTN_SHUTTER GPIO_NUM_0
#define LCD_CHUNK_LINES 20

// 相机引脚
#define CAM_PIN_XCLK  GPIO_NUM_15
#define CAM_PIN_SIOD  GPIO_NUM_4
#define CAM_PIN_SIOC  GPIO_NUM_5
#define CAM_PIN_D7    GPIO_NUM_16
#define CAM_PIN_D6    GPIO_NUM_17
#define CAM_PIN_D5    GPIO_NUM_18
#define CAM_PIN_D4    GPIO_NUM_12
#define CAM_PIN_D3    GPIO_NUM_10
#define CAM_PIN_D2    GPIO_NUM_8
#define CAM_PIN_D1    GPIO_NUM_9
#define CAM_PIN_D0    GPIO_NUM_11
#define CAM_PIN_VSYNC GPIO_NUM_6
#define CAM_PIN_HREF  GPIO_NUM_7
#define CAM_PIN_PCLK  GPIO_NUM_13

// ==================== COCO 类别名 (简写) ====================
static const char *coco_names[] = {
    "person","bicycle","car","motorbike","aeroplane","bus","train","truck","boat",
    "traffic light","fire hydrant","stop sign","parking meter","bench","bird","cat",
    "dog","horse","sheep","cow","elephant","bear","zebra","giraffe","backpack",
    "umbrella","handbag","tie","suitcase","frisbee","skis","snowboard","sports ball",
    "kite","baseball bat","baseball glove","skateboard","surfboard","tennis racket",
    "bottle","wine glass","cup","fork","knife","spoon","bowl","banana","apple",
    "sandwich","orange","broccoli","carrot","hot dog","pizza","donut","cake",
    "chair","sofa","potted plant","bed","dining table","toilet","tv monitor","laptop",
    "mouse","remote","keyboard","cell phone","microwave","oven","toaster","sink",
    "refrigerator","book","clock","vase","scissors","teddy bear","hair drier","toothbrush"
};

// ==================== 检测结果 ====================
typedef struct {
    float x1, y1, x2, y2; // LCD 坐标 (0-239)
    float score;
    int class_id;
} Detection;

// ==================== 简易字体 5x7 ====================
static const uint8_t font_5x7[][7] = {
    {0x0E,0x11,0x13,0x15,0x19,0x11,0x0E},{0x04,0x0C,0x04,0x04,0x04,0x04,0x0E},
    {0x0E,0x11,0x01,0x06,0x08,0x10,0x1F},{0x0E,0x11,0x01,0x06,0x01,0x11,0x0E},
    {0x02,0x06,0x0A,0x12,0x1F,0x02,0x02},{0x1F,0x10,0x1E,0x01,0x01,0x11,0x0E},
    {0x06,0x08,0x10,0x1E,0x11,0x11,0x0E},{0x1F,0x01,0x02,0x04,0x08,0x08,0x08},
    {0x0E,0x11,0x11,0x0E,0x11,0x11,0x0E},{0x0E,0x11,0x11,0x0F,0x01,0x02,0x0C},
    {0x00,0x00,0x00,0x00,0x00,0x00,0x04},{0x00,0x00,0x00,0x00,0x00,0x00,0x00},
};
static int char_to_idx(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c == '.') return 10;
    return 11; // space and others
}

// 在 buffer 上画小文字 (scale=1)
static void draw_char(uint16_t *buf, int bw, int bh, int x, int y, char c, uint16_t color) {
    int fi = char_to_idx(c);
    if (fi < 0 || fi > 11) fi = 11;
    for (int row = 0; row < 7; row++) {
        uint8_t bits = font_5x7[fi][row];
        for (int col = 0; col < 5; col++) {
            if (bits & (0x10 >> col)) {
                int px = x + col, py = y + row;
                if (px >= 0 && px < bw && py >= 0 && py < bh)
                    buf[py * bw + px] = color;
            }
        }
    }
}

static void draw_string(uint16_t *buf, int bw, int bh, int x, int y, const char *s, uint16_t color) {
    for (int i = 0; s[i] && i < 20; i++) {
        // 简单ASCII：字母用空格占位，只显示能渲染的字符
        draw_char(buf, bw, bh, x + i * 6, y, s[i], color);
    }
}

// 画矩形框
static void draw_rect(uint16_t *buf, int bw, int bh, int x1, int y1, int x2, int y2, uint16_t color, int thickness) {
    for (int t = 0; t < thickness; t++) {
        // 上边
        for (int x = x1; x <= x2; x++) {
            int py = y1 + t;
            if (x >= 0 && x < bw && py >= 0 && py < bh) buf[py * bw + x] = color;
        }
        // 下边
        for (int x = x1; x <= x2; x++) {
            int py = y2 - t;
            if (x >= 0 && x < bw && py >= 0 && py < bh) buf[py * bw + x] = color;
        }
        // 左边
        for (int y = y1; y <= y2; y++) {
            int px = x1 + t;
            if (px >= 0 && px < bw && y >= 0 && y < bh) buf[y * bw + px] = color;
        }
        // 右边
        for (int y = y1; y <= y2; y++) {
            int px = x2 - t;
            if (px >= 0 && px < bw && y >= 0 && y < bh) buf[y * bw + px] = color;
        }
    }
}

// ==================== LCD ====================

static void lcd_show_frame(esp_lcd_panel_handle_t lcd, const void *buf)
{
    const uint8_t *src = (const uint8_t *)buf;
    for (int y = 0; y < LCD_H; y += LCD_CHUNK_LINES) {
        int rows = LCD_CHUNK_LINES;
        if (y + rows > LCD_H) rows = LCD_H - y;
        esp_lcd_panel_draw_bitmap(lcd, 0, y, LCD_W, y + rows, src + y * LCD_W * 2);
    }
}

// ==================== 预处理 ====================

static void preprocess(const uint8_t *rgb565, int sw, int sh, int8_t *dst, int dw, int dh)
{
    float scx = (float)sw / dw, scy = (float)sh / dh;
    int plane = dw * dh;
    for (int y = 0; y < dh; y++) {
        int sy = (int)(y * scy); if (sy >= sh) sy = sh - 1;
        for (int x = 0; x < dw; x++) {
            int sx = (int)(x * scx); if (sx >= sw) sx = sw - 1;
            int idx = (sy * sw + sx) * 2;
            uint16_t p = (rgb565[idx] << 8) | rgb565[idx + 1];
            uint8_t r = ((p >> 11) & 0x1F) * 255 / 31;
            uint8_t g = ((p >> 5) & 0x3F) * 255 / 63;
            uint8_t b = (p & 0x1F) * 255 / 31;
            dst[0 * plane + y * dw + x] = (int8_t)(r - 128);
            dst[1 * plane + y * dw + x] = (int8_t)(g - 128);
            dst[2 * plane + y * dw + x] = (int8_t)(b - 128);
        }
    }
}

// ==================== 后处理 (NMS) ====================

static float iou(Detection *a, Detection *b) {
    float x1 = fmaxf(a->x1, b->x1), y1 = fmaxf(a->y1, b->y1);
    float x2 = fminf(a->x2, b->x2), y2 = fminf(a->y2, b->y2);
    float inter = fmaxf(0, x2 - x1) * fmaxf(0, y2 - y1);
    float area_a = (a->x2 - a->x1) * (a->y2 - a->y1);
    float area_b = (b->x2 - b->x1) * (b->y2 - b->y1);
    return inter / (area_a + area_b - inter + 1e-6f);
}

/**
 * 解码 YOLOX 输出 [1, 3549, 85] → Detection 数组
 * 返回检测到的目标数量
 */
static int postprocess(int8_t *output_data, int output_exp, int num_boxes,
                       Detection *dets, int max_dets)
{
    float scale = powf(2.0f, (float)output_exp);
    int count = 0;

    // 第一轮：筛选置信度高的框
    for (int i = 0; i < num_boxes && count < max_dets * 5; i++) {
        int8_t *row = output_data + i * BOX_DIM;

        // objectness score
        float obj = (float)row[4] * scale;
        obj = 1.0f / (1.0f + expf(-obj)); // sigmoid

        if (obj < 0.1f) continue; // 快速过滤

        // 找最大类别分数
        int best_cls = 0;
        float best_cls_score = -999.0f;
        for (int c = 0; c < NUM_CLASSES; c++) {
            float s = (float)row[5 + c] * scale;
            if (s > best_cls_score) { best_cls_score = s; best_cls = c; }
        }
        best_cls_score = 1.0f / (1.0f + expf(-best_cls_score)); // sigmoid
        float conf = obj * best_cls_score;

        if (conf < CONF_THRESH) continue;

        // 解码 bbox (YOLOX 输出是中心点 + 宽高，在模型输入 416x416 坐标系)
        float cx = (float)row[0] * scale;
        float cy = (float)row[1] * scale;
        float w  = (float)row[2] * scale;
        float h  = (float)row[3] * scale;

        // 转换到 LCD 坐标 (0-239)
        float ratio = (float)LCD_W / MODEL_W;
        float x1 = (cx - w / 2.0f) * ratio;
        float y1 = (cy - h / 2.0f) * ratio;
        float x2 = (cx + w / 2.0f) * ratio;
        float y2 = (cy + h / 2.0f) * ratio;

        // 裁剪到屏幕范围
        if (x1 < 0) x1 = 0; if (y1 < 0) y1 = 0;
        if (x2 >= LCD_W) x2 = LCD_W - 1; if (y2 >= LCD_H) y2 = LCD_H - 1;
        if (x2 <= x1 || y2 <= y1) continue;

        dets[count].x1 = x1; dets[count].y1 = y1;
        dets[count].x2 = x2; dets[count].y2 = y2;
        dets[count].score = conf;
        dets[count].class_id = best_cls;
        count++;
    }

    // NMS
    for (int i = 0; i < count; i++) {
        if (dets[i].score == 0) continue;
        for (int j = i + 1; j < count; j++) {
            if (dets[j].score == 0) continue;
            if (dets[i].class_id == dets[j].class_id && iou(&dets[i], &dets[j]) > NMS_THRESH) {
                dets[j].score = 0; // 抑制
            }
        }
    }

    // 压缩结果
    int final_count = 0;
    for (int i = 0; i < count && final_count < max_dets; i++) {
        if (dets[i].score > 0) {
            dets[final_count] = dets[i];
            final_count++;
        }
    }
    return final_count;
}

// ==================== 颜色表 ====================
static uint16_t class_colors[] = {
    0xF800, // 红
    0x07E0, // 绿
    0x001F, // 蓝
    0xFFE0, // 黄
    0xF81F, // 品红
    0x07FF, // 青
    0xFD20, // 橙
    0x780F, // 紫
    0x03EF, // 深青
    0xAFE5, // 浅绿
};

// ==================== 主程序 ====================

extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== YOLOX-Nano Detection - ESP32-S3-EYE ===");

    // 按键
    gpio_config_t btn_cfg = {};
    btn_cfg.pin_bit_mask = (1ULL << BTN_SHUTTER);
    btn_cfg.mode = GPIO_MODE_INPUT;
    btn_cfg.pull_up_en = GPIO_PULLUP_ENABLE;
    gpio_config(&btn_cfg);

    // LCD
    esp_lcd_panel_handle_t lcd = NULL;
    esp_lcd_panel_io_handle_t lcd_io = NULL;
    const bsp_display_config_t disp_cfg = { .max_transfer_sz = LCD_W * LCD_CHUNK_LINES * 2 + 100 };
    ESP_ERROR_CHECK(bsp_display_new(&disp_cfg, &lcd, &lcd_io));
    ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(lcd, true));
    bsp_display_backlight_on();

    // 摄像头
    camera_config_t cam_cfg = {};
    cam_cfg.pin_pwdn = (gpio_num_t)-1;
    cam_cfg.pin_reset = (gpio_num_t)-1;
    cam_cfg.pin_xclk = CAM_PIN_XCLK;
    cam_cfg.pin_sccb_sda = CAM_PIN_SIOD;
    cam_cfg.pin_sccb_scl = CAM_PIN_SIOC;
    cam_cfg.pin_d7 = CAM_PIN_D7; cam_cfg.pin_d6 = CAM_PIN_D6;
    cam_cfg.pin_d5 = CAM_PIN_D5; cam_cfg.pin_d4 = CAM_PIN_D4;
    cam_cfg.pin_d3 = CAM_PIN_D3; cam_cfg.pin_d2 = CAM_PIN_D2;
    cam_cfg.pin_d1 = CAM_PIN_D1; cam_cfg.pin_d0 = CAM_PIN_D0;
    cam_cfg.pin_vsync = CAM_PIN_VSYNC;
    cam_cfg.pin_href = CAM_PIN_HREF;
    cam_cfg.pin_pclk = CAM_PIN_PCLK;
    cam_cfg.xclk_freq_hz = 16000000;
    cam_cfg.ledc_timer = LEDC_TIMER_0;
    cam_cfg.ledc_channel = LEDC_CHANNEL_0;
    cam_cfg.pixel_format = PIXFORMAT_RGB565;
    cam_cfg.frame_size = FRAMESIZE_240X240;
    cam_cfg.fb_count = 2;
    cam_cfg.fb_location = CAMERA_FB_IN_PSRAM;
    cam_cfg.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
    ESP_ERROR_CHECK(esp_camera_init(&cam_cfg));
    sensor_t *s = esp_camera_sensor_get();
    if (s) { s->set_vflip(s, 1); s->set_hmirror(s, 0); }

    // 模型
    dl::Model *model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model FAILED"); while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }

    // 分配检测结果画面缓冲（PSRAM）
    uint16_t *result_frame = (uint16_t *)heap_caps_malloc(LCD_W * LCD_H * 2, MALLOC_CAP_SPIRAM);
    Detection dets[MAX_DET * 5]; // 临时存放（NMS 前可能多于 MAX_DET）

    ESP_LOGI(TAG, "Ready! Press BOOT to detect.");

    bool showing = false;
    int countdown = 0;

    while (1) {
        bool btn = (gpio_get_level(BTN_SHUTTER) == 0);

        if (btn && !showing) {
            // ====== 拍照 + 检测 ======
            camera_fb_t *fb = esp_camera_fb_get();
            if (!fb) { vTaskDelay(pdMS_TO_TICKS(50)); continue; }

            // 保存画面用于画框
            memcpy(result_frame, fb->buf, LCD_W * LCD_H * 2);

            // 预处理
            int8_t *model_input = (int8_t *)inputs.begin()->second->get_element_ptr();
            preprocess(fb->buf, fb->width, fb->height, model_input, MODEL_W, MODEL_H);
            esp_camera_fb_return(fb);

            // 推理
            model->run();

            // 后处理
            auto &outputs = model->get_outputs();
            int num_dets = 0;
            if (!outputs.empty()) {
                auto out = outputs.begin()->second;
                int8_t *out_data = (int8_t *)out->get_element_ptr();
                int out_exp = out->get_exponent();
                num_dets = postprocess(out_data, out_exp, NUM_BOXES, dets, MAX_DET);
            }

            // 在画面上画检测框
            for (int i = 0; i < num_dets; i++) {
                uint16_t color = class_colors[dets[i].class_id % 10];
                int x1 = (int)dets[i].x1, y1 = (int)dets[i].y1;
                int x2 = (int)dets[i].x2, y2 = (int)dets[i].y2;

                // 画框 (2像素粗)
                draw_rect(result_frame, LCD_W, LCD_H, x1, y1, x2, y2, color, 2);

                // 画类别名（框上方）
                const char *name = coco_names[dets[i].class_id % NUM_CLASSES];
                char label[24];
                snprintf(label, sizeof(label), "%s", name);
                int ty = y1 - 8;
                if (ty < 0) ty = y1 + 2;
                draw_string(result_frame, LCD_W, LCD_H, x1 + 2, ty, label, color);
            }

            // 画检测数量
            char info[16];
            snprintf(info, sizeof(info), "%d obj", num_dets);
            draw_string(result_frame, LCD_W, LCD_H, 5, LCD_H - 12, info, 0x07E0);

            // 显示结果画面
            lcd_show_frame(lcd, result_frame);

            showing = true;
            countdown = 80; // ~4 秒

            while (gpio_get_level(BTN_SHUTTER) == 0) vTaskDelay(pdMS_TO_TICKS(20));
            vTaskDelay(pdMS_TO_TICKS(100));

        } else if (showing) {
            countdown--;
            if (countdown <= 0) showing = false;
            vTaskDelay(pdMS_TO_TICKS(50));

        } else {
            // ====== 实时预览 ======
            camera_fb_t *fb = esp_camera_fb_get();
            if (fb) {
                lcd_show_frame(lcd, fb->buf);
                esp_camera_fb_return(fb);
            }
            vTaskDelay(pdMS_TO_TICKS(10));
        }
    }
}

