// ==================== 预处理 ====================
// ESP-DL 将输入转为 NHWC 格式，exponent=1 表示 float = int8 * 2
// 原始预处理: pixel [0,255] / 255.0 => [0,1]
// 量化: [0,1] / 2^exponent => [0,1] / 2 => int8 range [0, 127]
// 简化: int8_val = pixel / 255.0 / 2^exponent = pixel / (255 * 2^exp)
static void preprocess(const uint8_t *rgb565, int sw, int sh, int8_t *dst, int dw, int dh, int exponent) {
    float scale_factor = 1.0f / (255.0f * powf(2.0f, (float)exponent));
    float scx = (float)sw / dw, scy = (float)sh / dh;

    for (int y = 0; y < dh; y++) {
        int sy = (int)(y * scy);
        if (sy >= sh) sy = sh - 1;
        for (int x = 0; x < dw; x++) {
            int sx = (int)(x * scx);
            if (sx >= sw) sx = sw - 1;
            int idx = (sy * sw + sx) * 2;
            uint16_t p = (rgb565[idx] << 8) | rgb565[idx+1];
            float r = ((p>>11)&0x1F)*(255.0f/31.0f);
            float g = ((p>>5)&0x3F)*(255.0f/63.0f);
            float b = (p&0x1F)*(255.0f/31.0f);

            // NHWC 格式: dst[y * W * 3 + x * 3 + c]
            int off = (y * dw + x) * 3;
            dst[off + 0] = (int8_t)fmaxf(-128, fminf(127, r * scale_factor));
            dst[off + 1] = (int8_t)fmaxf(-128, fminf(127, g * scale_factor));
            dst[off + 2] = (int8_t)fmaxf(-128, fminf(127, b * scale_factor));
        }
    }
}

