{
    // exponent=-6: scale = 2^(-6) = 1/64
    // int8=64 → float=1.0 (sigmoid max)
    const float scale = powf(2.0f, (float)exponent);
    const int stride = strides[layer_idx];

    for (int cy = 0; cy < gh; cy++) {
        for (int cx = 0; cx < gw; cx++) {
            // 95 channels per grid cell (HWC layout)
            int base = (cy * gw + cx) * OUTPUT_CH;

            for (int a = 0; a < ANCHOR_NUM; a++) {
                // Objectness: offset 12 + a
                float obj = (float)data[base + 12 + a] * scale;
                if (obj < CONF_THRESH) continue;

                // Class probabilities: offset 15..94 (shared by all anchors)
                int best_cls = 0;
                float best_prob = 0;
                for (int c = 0; c < NUM_CLASSES; c++) {
                    float p = (float)data[base + 15 + c] * scale;
                    if (p > best_prob) {
                        best_prob = p;
                        best_cls = c;
                    }
                }

                float conf = obj * best_prob;
                if (conf < CONF_THRESH) continue;

                // Regression: offset a*4 .. a*4+3 (already sigmoid'd, 0-1)
                float tx = (float)data[base + a * 4 + 0] * scale;
                float ty = (float)data[base + a * 4 + 1] * scale;
                float tw = (float)data[base + a * 4 + 2] * scale;
                float th = (float)data[base + a * 4 + 3] * scale;

                // Decode bbox (YOLOv5-style)
                float bx = (tx * 2.0f - 0.5f + (float)cx) * (float)stride;
                float by = (ty * 2.0f - 0.5f + (float)cy) * (float)stride;
                float bw = (tw * 2.0f) * (tw * 2.0f) * anchors[layer_idx][a][0];
                float bh = (th * 2.0f) * (th * 2.0f) * anchors[layer_idx][a][1];

                // Convert to normalized [0,1] coordinates
                float x1 = (bx - bw * 0.5f) / (float)MODEL_W;
                float y1 = (by - bh * 0.5f) / (float)MODEL_H;
                float x2 = (bx + bw * 0.5f) / (float)MODEL_W;
                float y2 = (by + bh * 0.5f) / (float)MODEL_H;

                // Clip
                if (x1 < 0) x1 = 0;
                if (y1 < 0) y1 = 0;
                if (x2 > 1) x2 = 1;
                if (y2 > 1) y2 = 1;
                if (x2 - x1 < 0.01f || y2 - y1 < 0.01f) continue;

                if (cnt < MAX_DET) {
                    dets[cnt].x1 = x1;
                    dets[cnt].y1 = y1;
                    dets[cnt].x2 = x2;
                    dets[cnt].y2 = y2;
                    dets[cnt].score = conf;
                    dets[cnt].class_id = best_cls;
                    cnt++;
                }
            }
        }
    }
    return cnt;
}

// ==================== NMS ====================
static float compute_iou(Det *a, Det *b)
{
    float ix1 = fmaxf(a->x1, b->x1);
    float iy1 = fmaxf(a->y1, b->y1);
    float ix2 = fminf(a->x2, b->x2);
    float iy2 = fminf(a->y2, b->y2);
    float inter = fmaxf(0, ix2 - ix1) * fmaxf(0, iy2 - iy1);
    float area_a = (a->x2 - a->x1) * (a->y2 - a->y1);
    float area_b = (b->x2 - b->x1) * (b->y2 - b->y1);
    return inter / (area_a + area_b - inter + 1e-6f);
}

static int nms(Det *dets, int count)
{
    // Sort by confidence (descending)
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (dets[j].score > dets[i].score) {
                Det tmp = dets[i];
                dets[i] = dets[j];
                dets[j] = tmp;
            }
        }
    }
    // Suppress
    for (int i = 0; i < count; i++) {
        if (dets[i].score < 0) continue;
        for (int j = i + 1; j < count; j++) {
            if (dets[j].score < 0) continue;
            if (dets[i].class_id == dets[j].class_id &&
                compute_iou(&dets[i], &dets[j]) > NMS_THRESH) {
                dets[j].score = -1;
            }
        }
    }
    // Compact
    int valid = 0;
    for (int i = 0; i < count; i++) {
        if (dets[i].score >= 0) {
            if (valid != i) dets[valid] = dets[i];
            valid++;
        }
    }
    return valid;
}

// ==================== 推理任务 (Core 1) ====================
static void inference_task(void *arg)
{
    auto &inputs = s_model->get_inputs();
    int8_t *model_input = (int8_t *)inputs.begin()->second->get_element_ptr();

    Det local_dets[MAX_DET];
    int frame_num = 0;

    ESP_LOGI("infer", "Task started on Core 1");

    while (1) {
        // 等待新帧
        if (!s_new_frame_ready) {
            vTaskDelay(pdMS_TO_TICKS(5));
            continue;
        }
        s_new_frame_ready = false;
        frame_num++;

        // 预处理: 240x240 RGB565 → 224x224 INT8 NHWC
        preprocess(s_infer_buf, LCD_W, LCD_H, model_input, MODEL_W, MODEL_H);

        // 推理
        s_model->run();

        // 后处理：解码两个输出头
        int dc = 0;
        auto &outs = s_model->get_outputs();

        for (auto &kv : outs) {
            auto tensor = kv.second;
            int8_t *out_data = (int8_t *)tensor->get_element_ptr();
            int out_exp = tensor->get_exponent();
            int size = tensor->get_size();

            // 根据 tensor size 判断是哪个 grid
            // 14*14*95 = 18620, 7*7*95 = 4655
            int layer_idx;
            int gh, gw;
            if (size == 14 * 14 * 95) {
                layer_idx = 0; gh = 14; gw = 14;
            } else if (size == 7 * 7 * 95) {
                layer_idx = 1; gh = 7; gw = 7;
            } else {
                ESP_LOGW("infer", "Unknown output size %d, skipping", size);
                continue;
            }

            dc = decode_layer(out_data, gh, gw, out_exp, layer_idx, local_dets, dc);
        }

        dc = nms(local_dets, dc);

        // 更新共享检测结果
        xSemaphoreTake(s_det_mutex, portMAX_DELAY);
        s_det_count = dc;
        if (dc > 0) {
            memcpy(s_detections, local_dets, dc * sizeof(Det));
        }
        xSemaphoreGive(s_det_mutex);

        if (frame_num % 10 == 1) {
            ESP_LOGI("infer", "Frame %d: %d detections", frame_num, dc);
        }

        // 让出 CPU
        vTaskDelay(pdMS_TO_TICKS(1));
    }
}

