    cc.fb_location = CAMERA_FB_IN_PSRAM;
    cc.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
    ESP_ERROR_CHECK(esp_camera_init(&cc));
    sensor_t *s = esp_camera_sensor_get();
    if (s) {
        s->set_vflip(s, 1);
        s->set_hmirror(s, 0);
    }
    ESP_LOGI(TAG, "Camera OK");

    // ===== Model =====
    ESP_LOGI(TAG, "Loading model...");
    s_model = new dl::Model("model", fbs::MODEL_LOCATION_IN_FLASH_PARTITION);
    auto &inputs = s_model->get_inputs();
    if (inputs.empty()) {
        ESP_LOGE(TAG, "Model load FAILED!");
        while (1) vTaskDelay(pdMS_TO_TICKS(10000));
    }
    ESP_LOGI(TAG, "Model OK. Input exponent=%d, size=%d",
             inputs.begin()->second->get_exponent(),
             inputs.begin()->second->get_size());

    // ===== Allocate shared resources =====
    s_det_mutex = xSemaphoreCreateMutex();
    s_infer_buf = (uint8_t *)heap_caps_malloc(LCD_W * LCD_H * 2, MALLOC_CAP_SPIRAM);
    uint16_t *disp_buf = (uint16_t *)heap_caps_malloc(LCD_W * LCD_H * 2, MALLOC_CAP_SPIRAM);

    if (!s_infer_buf || !disp_buf) {
        ESP_LOGE(TAG, "Memory allocation failed!");
        return;
    }

    // ===== Start inference task on Core 1 =====
    xTaskCreatePinnedToCore(inference_task, "infer", 32768, NULL, 5, NULL, 1);
    ESP_LOGI(TAG, "Inference task started. Running...");

    // ===== Main loop: capture + overlay + display =====
    while (1) {
        // 取帧
        camera_fb_t *fb = esp_camera_fb_get();
        if (!fb) {
            vTaskDelay(pdMS_TO_TICKS(5));
            continue;
        }

        // 如果推理线程空闲，送一帧新数据
        if (!s_new_frame_ready) {
            memcpy(s_infer_buf, fb->buf, LCD_W * LCD_H * 2);
            s_new_frame_ready = true;
        }

        // 拷贝当前帧到显示缓冲
        memcpy(disp_buf, fb->buf, LCD_W * LCD_H * 2);
        esp_camera_fb_return(fb);

        // 叠加检测框
        xSemaphoreTake(s_det_mutex, portMAX_DELAY);
        int det_count = s_det_count;
        Det local_copy[MAX_DET];
        if (det_count > 0) {
            memcpy(local_copy, s_detections, det_count * sizeof(Det));
        }
        xSemaphoreGive(s_det_mutex);

        for (int i = 0; i < det_count; i++) {
            int bx1 = (int)(local_copy[i].x1 * LCD_W);
            int by1 = (int)(local_copy[i].y1 * LCD_H);
            int bx2 = (int)(local_copy[i].x2 * LCD_W);
            int by2 = (int)(local_copy[i].y2 * LCD_H);
            uint16_t color = det_colors[local_copy[i].class_id % 10];

            draw_box(disp_buf, bx1, by1, bx2, by2, color);

            // 在框左上角画一个 10x10 色块标识
            int lx = bx1;
            int ly = (by1 >= 11) ? by1 - 11 : by1 + 3;
            for (int py = ly; py < ly + 10 && py < LCD_H; py++) {
                for (int px = lx; px < lx + 10 && px < LCD_W; px++) {
                    if (px >= 0 && py >= 0)
                        disp_buf[py * LCD_W + px] = color;
                }
            }
        }

        // 推送到 LCD
        lcd_show(lcd, disp_buf);
    }
}

