input.oldStr:
// ==================== 预处理 ====================
// 输入: RGB565 相机帧 (240x240)
// 输出: INT8 NHWC (224x224x3), exponent=1
// 量化: int8_val = pixel_float_0_1 / 2^1 = (pixel_0_255 / 255.0) / 2
//       但这会太小。实际上 exponent=1 意味着 float = int8 * 2，
//       所以 int8 = float / 2。原始输入 [0,1] -> int8 = [0, 0.5] -> 全0。
//       实际上校准时用的是 pixel[0,255]/255 = [0,1]，量化器选了 exponent=1
//       说明 int8 范围 [-256, 254] 可以表示 [0,1]：int8=0 对应 float=0，
//       int8=0.5/2=不对...
//
// 经过仔细分析：exponent=1 对应 scale=2, 表示 1 个 int8 step = 2.0。
// 校准时输入 [0,1]，int8 最大值 = 1.0/2.0 = 0.5 -> int8=0。
// 这说明量化器期望的输入不是 [0,1] 而是 [0,255]！
// 验证: int8_max = 255/2 = 127 (刚好占满 int8 正数范围)
// 结论: 直接传 pixel/2 作为 int8 输入。
static void preprocess(const uint8_t *rgb565, int sw, int sh,
                       int8_t *dst, int dw, int dh)
{
    const float scx = (float)sw / dw;
    const float scy = (float)sh / dh;

    for (int y = 0; y < dh; y++) {
        int sy = (int)(y * scy);
        if (sy >= sh) sy = sh - 1;
        for (int x = 0; x < dw; x++) {
            int sx = (int)(x * scx);
            if (sx >= sw) sx = sw - 1;

            // esp32-camera RGB565 大端: byte0=high, byte1=low
            int idx = (sy * sw + sx) * 2;
            uint16_t p = (rgb565[idx] << 8) | rgb565[idx + 1];
            uint8_t r = ((p >> 11) & 0x1F) * 255 / 31;
            uint8_t g = ((p >> 5) & 0x3F) * 255 / 63;
            uint8_t b = (p & 0x1F) * 255 / 31;

            // NHWC 格式, int8 = pixel / 2
            int off = (y * dw + x) * 3;
            dst[off + 0] = (int8_t)(r >> 1);
            dst[off + 1] = (int8_t)(g >> 1);
            dst[off + 2] = (int8_t)(b >> 1);
        }
    }
}

