// ==================== 预处理 ====================
// 输入: RGB565 相机帧 (240x240)
// 输出: INT8 NHWC (224x224x3)
// 新量化模型 exponent=-6: float = int8 * 2^(-6) = int8/64
// 模型期望 float [0, 1]: int8 = float * 64 = (pixel/255) * 64 = pixel * 64 / 255 ≈ pixel / 4
static void preprocess(const uint8_t *rgb565, int sw, int sh,
                       int8_t *dst, int dw, int dh)
{
    const float scx = (float)sw / dw;
    const float scy = (float)sh / dh;

    for (int y = 0; y < dh; y++) {
        int sy = (int)(y * scy);
        if (sy >= sh) sy = sh - 1;
        for (int x = 0; x < dw; x++) {
            int sx = (int)(x * scx);
            if (sx >= sw) sx = sw - 1;

            int idx = (sy * sw + sx) * 2;
            uint16_t p = (rgb565[idx] << 8) | rgb565[idx + 1];
            uint8_t r = ((p >> 11) & 0x1F) * 255 / 31;
            uint8_t g = ((p >> 5) & 0x3F) * 255 / 63;
            uint8_t b = (p & 0x1F) * 255 / 31;

            // int8 = (pixel / 255.0) * 64 = pixel / 4 (近似)
            int off = (y * dw + x) * 3;
            dst[off + 0] = (int8_t)(r >> 2);
            dst[off + 1] = (int8_t)(g >> 2);
            dst[off + 2] = (int8_t)(b >> 2);
        }
    }
}

