static void draw_char_at(uint16_t *buf, int bw, int bh, int x, int y, char c, uint16_t color)
{
    // 转大写
    if (c >= 'a' && c <= 'z') c -= 32;
    if (c < 'A' || c > 'Z') return; // 只画字母

    const uint8_t *glyph = font_upper[c - 'A'];
    for (int row = 0; row < 7; row++) {
        uint8_t bits = glyph[row];
        for (int col = 0; col < 5; col++) {
            if (bits & (0x10 >> col)) {
                int px = x + col;
                int py = y + row;
                if (px >= 0 && px < bw && py >= 0 && py < bh) {
                    buf[py * bw + px] = color;
                }
            }
        }
    }
}

static void draw_label(uint16_t *buf, int bw, int bh, int x, int y,
                       const char *text, uint16_t fg_color, uint16_t bg_color)
{
    // 计算文字长度（最多8个字符）
    int len = 0;
    while (text[len] && len < 8) len++;

    // 画背景条
    int pad = 1;
    int tw = len * 6 + pad * 2;
    int th = 7 + pad * 2;
    for (int py = y; py < y + th && py < bh; py++) {
        for (int px = x; px < x + tw && px < bw; px++) {
            if (px >= 0 && py >= 0) buf[py * bw + px] = bg_color;
        }
    }

    // 画文字
    for (int i = 0; i < len; i++) {
        draw_char_at(buf, bw, bh, x + pad + i * 6, y + pad, text[i], fg_color);
    }
}

