"""NIMA 美学评分器（主进程侧）。

NIMA 依赖 TensorFlow + Python 3.10，与主环境(PyTorch/py3.12)不兼容，
因此通过子进程调用 nima_worker.py（在 NIMA 的 TF venv 中运行），
一次子进程批量处理多张图，返回美学分(1-10)。
"""
import os, sys, json, subprocess

_HERE = os.path.dirname(os.path.abspath(__file__))
_ROOT = os.path.dirname(_HERE)

# NIMA 的 TF 虚拟环境 python
NIMA_PYTHON = r"C:\Users\MI\Desktop\NIMA-Aesthetic\.venv\Scripts\python.exe"
WORKER = os.path.join(_HERE, "nima_worker.py")


class AestheticScorer:
    name = "aesthetic"
    raw_range = (1.0, 10.0)  # NIMA 1-10 分制

    def __init__(self, device="cpu"):
        if not os.path.isfile(NIMA_PYTHON):
            raise RuntimeError(f"找不到 NIMA venv: {NIMA_PYTHON}")

    def score_batch(self, img_paths):
        """批量打分，返回 {path: score}。一次子进程处理所有图。"""
        proc = subprocess.run(
            [NIMA_PYTHON, WORKER, *img_paths],
            capture_output=True, text=True, encoding="utf-8",
        )
        results = {}
        for line in proc.stdout.splitlines():
            line = line.strip()
            if not line.startswith("{"):
                continue
            try:
                obj = json.loads(line)
                if "score" in obj:
                    results[obj["path"]] = obj["score"]
            except json.JSONDecodeError:
                pass
        if not results and proc.returncode != 0:
            raise RuntimeError(f"NIMA worker 失败:\n{proc.stderr[-800:]}")
        return results

    def score(self, img_path):
        r = self.score_batch([img_path])
        return float(r.get(img_path, float("nan")))


if __name__ == "__main__":
    import glob
    s = AestheticScorer()
    paths = sorted(glob.glob(os.path.join(_ROOT, "test_images", "*.jpg")))
    res = s.score_batch(paths)
    for p in paths:
        print(os.path.basename(p), round(res.get(p, float("nan")), 4))

"""融合引擎：五维度归一化 + 加权融合 + 规则建议生成。"""

# 维度权重（与方案一致）
WEIGHTS = {
    "beauty":       0.30,   # 颜值 SCUT
    "aesthetic":    0.25,   # 美学 NIMA
    "exposure":     0.20,   # 曝光 统计
    "face_quality": 0.15,   # 人脸质量 统计
    "composition":  0.10,   # 构图 SAMP
}

# 各维度原始分制（用于归一化到 0-1）
RAW_RANGE = {
    "beauty":       (1.0, 5.0),
    "aesthetic":    (1.0, 10.0),
    "exposure":     (0.0, 1.0),
    "face_quality": (0.0, 1.0),
    "composition":  (1.0, 5.0),
}

DIM_CN = {
    "beauty": "颜值", "aesthetic": "美学", "exposure": "曝光",
    "face_quality": "人脸清晰度", "composition": "构图",
}


def normalize(dim, raw):
    lo, hi = RAW_RANGE[dim]
    return max(0.0, min(1.0, (raw - lo) / (hi - lo + 1e-9)))


def fuse(raw_scores):
    """raw_scores: {dim: 原始分}。返回 (总分0-100, 各维归一化分, 明细)。"""
    norm = {d: normalize(d, v) for d, v in raw_scores.items() if d in WEIGHTS}
    total_w = sum(WEIGHTS[d] for d in norm)
    weighted = sum(norm[d] * WEIGHTS[d] for d in norm) / (total_w + 1e-9)
    total_100 = round(weighted * 100, 1)
    return total_100, norm


def make_suggestions(raw_scores, norm, exposure_detail=None, face_detail=None):
    """基于分数与统计诊断生成文字建议（规则模板，无 LLM）。"""
    tips = []

    # 曝光：优先用统计模块的诊断标签，最精准
    tags = (exposure_detail or {}).get("tags", [])
    if "高光过曝" in tags:
        tips.append("画面高光过曝，建议避开强光或降低曝光。")
    if "暗部欠曝" in tags or "整体偏暗" in tags:
        tips.append("光线偏暗，建议增加环境光或提高亮度。")
    if "整体偏亮" in tags and "高光过曝" not in tags:
        tips.append("画面偏亮，可适当降低曝光。")
    if "层次偏平" in tags:
        tips.append("明暗层次偏平，可增强对比。")

    # 人脸清晰度
    if norm.get("face_quality", 1) < 0.5:
        tips.append("人脸不够清晰，注意对焦、保持稳定或靠近光源。")

    # 构图
    if norm.get("composition", 1) < 0.45:
        tips.append("构图可优化，尝试三分法、让主体更居中或平衡画面。")

    # 美学 / 颜值偏低时的柔性提示
    if norm.get("aesthetic", 1) < 0.4:
        tips.append("整体观感一般，可换个背景或角度试试。")

    if not tips:
        tips.append("整体表现不错，保持当前状态即可。")

    # 找出最弱维度，给一句总括
    if norm:
        weak = min(norm, key=norm.get)
        tips.insert(0, f"最需要改进的是「{DIM_CN.get(weak, weak)}」。")
    return tips


def grade(total_100):
    if total_100 >= 80: return "优秀"
    if total_100 >= 65: return "良好"
    if total_100 >= 50: return "中等"
    if total_100 >= 35: return "偏低"
    return "较差"

