    if ($item.PSIsContainer) {
      $n = (Get-ChildItem $p -File -ErrorAction SilentlyContinue).Count
      Write-Output ("[存在-目录] {0}  ({1} 个文件)" -f $p, $n)
    } else {
      Write-Output ("[存在-文件] {0}  ({1:N1} KB)" -f $p, ($item.Length/1KB))
    }
  } else {
    Write-Output ("[缺失]     {0}" -f $p)
  }
}
